/**
 * The analytics building blocks, split by concern under `./analytics/` and re-exported here so the public names
 * and this import path stay stable. Fixtures (the PRNG, `DEMO_NOW`, demo series and loaders) are NOT here: they
 * live in `../demo-data.ts`, which the package root does not export.
 */
export * from "./analytics/data";
export * from "./analytics/labels";
export * from "./analytics/hooks";
export * from "./analytics/glass";
export * from "./analytics/shell";
export * from "./analytics/panel";
export * from "./analytics/kpi";
export * from "./analytics/trend-chart";
export * from "./analytics/stacked-trend-chart";
export * from "./analytics/bar-trend-chart";

"use client";

import { memo, useEffect, useId, useMemo, useRef } from "react";

import { AnimatePresence, animate, motion, useMotionValue, useMotionValueEvent } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, ease } from "../../motion/tokens";

import { ChartEmpty, type TooltipRow } from "../../charts/chart-parts";
import {
  axisFormat,
  barPath,
  chartGlow,
  clamp,
  formatCompact,
  linePath,
  slotColor,
  useDataChanged,
  type ChartColor,
} from "../../charts/chart-utils";

import { changeRatio, formatChange } from "./data";
import { type AnalyticsLabels, defaultAnalyticsLabels } from "./labels";
import {
  ChartReader,
  FrameAxes,
  type FrameGeometry,
  WipeClip,
  easeOutCubic,
  frameGeometry,
  trendSpring,
  useDashChart,
} from "./trend-frame";

/* ---------- BarTrendChart: bars + line on one axis ---------- */

/** One bar of a `BarTrendChart`. */
export type BarTrendDatum = {
  /** Short axis label. */
  label: string;
  /** Longer label for the tooltip and announcements (defaults to `label`). */
  long?: string;
  /** The bar's value (`number`). */
  value: number;
  /** The line (a moving average, a target… same unit as the bars). */
  line?: number | null;
  /** Same point of the previous period (dashed when `compare`). */
  previous?: number | null;
};

/** Props of `BarTrendChart`. */
export type BarTrendChartProps = {
  /** Lists the bars, oldest first (`BarTrendDatum[]`, required). */
  data: BarTrendDatum[];
  /** Name of the bar series (`string`, required): tooltip and table. */
  seriesLabel: string;
  /** Name of the line series (omit to hide the line). */
  lineLabel?: string;
  /** Sets the palette slot (1–8) used for the bars. Default 1. */
  color?: ChartColor;
  /** Sets the palette slot (1–8) used for the line. Default 2. */
  lineColor?: ChartColor;
  /** Draw the previous period as a dashed, muted line. */
  compare?: boolean;
  /** Sets the plot height in pixels (`number`, default 300). */
  height?: number;
  /** Formats values in the axis and tooltip (`(n: number) => string`, default compact). */
  format?: (n: number) => string;
  /** BCP 47 locale for dates and numbers in announcements (`string`, default the runtime's). */
  locale?: string;
  /** Overrides for the chart's strings. */
  labels?: Partial<
    Pick<AnalyticsLabels, "previousPeriod" | "changeLabel" | "chartInstructions" | "touchHint" | "noData">
  >;
  /** Names the chart for assistive tech (`string`, required). */
  "aria-label": string;
  /** Adds extra classes to the chart's wrapper (`string`). */
  className?: string;
};

/**
 * Bars (≤ 24px, rounded data-end, 2px gaps) with a line on the same axis and the previous
 * period dashed. All bars are ONE path driven by one progress value: they grow from the
 * baseline in a wave on first view and tween on new data, at the cost of a single element.
 *
 * Props (see `BarTrendChartProps`): `data`, `seriesLabel` and `aria-label` are required; `lineLabel`
 * (omit to hide the line), `color` (`1`), `lineColor` (`2`), `compare` (`false`), `height` (`300`),
 * `format`, `locale`, `labels`, `className`.
 * Keyboard: Tab focuses the chart; the arrow keys move between bars, Home and End jump to the ends,
 * Escape clears; each move announces the bar, the line value and the change.
 * Accessibility: `role="figure"` named by `aria-label`; the line and the previous period differ by
 * shape (solid or dashed), not just colour.
 * Glass and motion: no backdrop blur on the plot; the tooltip is the shared glass surface. Bars grow
 * in once; reduced motion draws them in place.
 *
 * @example
 * ```tsx
 * import { BarTrendChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <BarTrendChart
 *       seriesLabel="Orders"
 *       lineLabel="7-day average"
 *       aria-label="Orders per day"
 *       data={[{ label: "Mon", value: 42, line: 38 }, { label: "Tue", value: 51, line: 40 }, { label: "Wed", value: 47, line: 43 }]}
 *     />
 *   );
 * }
 * ```
 *
 * @see /dashboards/ecommerce
 */
export function BarTrendChart({
  data,
  seriesLabel,
  lineLabel,
  color = 1,
  lineColor = 2,
  compare = false,
  height = 300,
  format = formatCompact,
  locale,
  labels: labelsProp,
  "aria-label": ariaLabel,
  className,
}: BarTrendChartProps) {
  const t = { ...defaultAnalyticsLabels, ...labelsProp };
  const id = useId().replace(/:/g, "");
  const { ref: chartRef, svgRef, ...c } = useDashChart(height);
  const fill = slotColor(color);
  const lineStroke = slotColor(lineColor);
  const hasLine = Boolean(lineLabel) && data.some((d) => d.line != null);
  const hasPrev = compare && data.some((d) => d.previous != null);
  const tickFormat = axisFormat(format === formatCompact ? undefined : format);
  const signature = data.map((d) => `${d.value}|${d.line ?? ""}|${d.previous ?? ""}`).join(",") + (hasPrev ? "c" : "");

  const geo = useMemo(() => {
    let max = 0;
    for (const d of data) {
      max = Math.max(max, d.value, hasLine ? (d.line ?? 0) : 0, hasPrev ? (d.previous ?? 0) : 0);
    }
    const g = frameGeometry(
      data.map((d) => d.label),
      max,
      c.width,
      height,
      c.docked,
      tickFormat,
      true,
    );
    const barW = clamp(Math.min(24, g.step - 2), 1, 24);
    const heights = data.map((d) => g.innerH - g.y(d.value));
    const linePoints = data.map((d, i) => [g.xs[i] ?? 0, g.y(d.line ?? 0)] as const);
    const prevPoints = data.map((d, i) => [g.xs[i] ?? 0, g.y(d.previous ?? 0)] as const);
    return {
      g,
      barW,
      heights,
      linePoints,
      prevPoints,
      line: linePath(linePoints, "monotone"),
      prevLine: linePath(prevPoints, "monotone"),
    };
  }, [data, hasLine, hasPrev, c.width, height, c.docked, tickFormat]);

  const layers = useMemo(
    () => (
      <BarLayers
        geo={geo}
        labels={data}
        id={id}
        fill={fill}
        lineStroke={lineStroke}
        hasLine={hasLine}
        hasPrev={hasPrev}
        shown={c.shown}
        reduced={c.reduced}
        signature={signature}
        tickFormat={tickFormat}
      />
    ),
    [geo, data, id, signature, fill, lineStroke, hasLine, hasPrev, c.shown, c.reduced, tickFormat],
  );

  if (data.length === 0) {
    return (
      <div className={className}>
        <ChartEmpty height={height} aria-label={ariaLabel}>
          {t.noData}
        </ChartEmpty>
      </div>
    );
  }

  const rows = (i: number): TooltipRow[] => {
    const d = data[i];
    if (!d) return [];
    const out: TooltipRow[] = [{ label: seriesLabel, value: format(d.value), color: fill, kind: "rect" }];
    if (hasLine && d.line != null && lineLabel)
      out.push({ label: lineLabel, value: format(d.line), color: lineStroke });
    if (hasPrev && d.previous != null) {
      out.push({ label: t.previousPeriod, value: format(d.previous), color: "var(--sheen-fg-subtle)" });
      const r = changeRatio(d.value, d.previous);
      if (r !== null) out.push({ label: t.changeLabel, value: formatChange(r, locale), color: "transparent" });
    }
    return out;
  };
  const marks = (i: number) => {
    const h = geo.heights[i] ?? 0;
    const w = geo.barW;
    return (
      <>
        {/* The bar being read: a ring in the text colour (shape, not only colour) with a soft glow. */}
        <path
          d={barPath(-w / 2 - 1.5, geo.g.innerH - h - 1.5, w + 3, h + 1.5, "top", Math.min(5.5, w / 2 + 1.5))}
          fill="none"
          stroke="var(--sheen-fg)"
          strokeWidth={1.5}
          style={{ filter: chartGlow(fill, 8) }}
        />
        {hasLine && data[i]?.line != null && (
          <circle
            cy={geo.linePoints[i]?.[1]}
            r={4}
            fill={lineStroke}
            stroke="var(--sheen-chart-surface)"
            strokeWidth={2}
          />
        )}
        {hasPrev && data[i]?.previous != null && (
          <circle
            cy={geo.prevPoints[i]?.[1]}
            r={3.5}
            fill="var(--sheen-chart-surface)"
            stroke="var(--sheen-fg-subtle)"
            strokeWidth={1.5}
          />
        )}
      </>
    );
  };

  return (
    <div ref={chartRef} className={cn("relative w-full", className)} style={{ height }}>
      {c.width > 0 && (
        <ChartReader
          width={c.width}
          height={height}
          geo={geo.g}
          docked={c.docked}
          items={data}
          layers={layers}
          marks={marks}
          rows={rows}
          reduced={c.reduced}
          svgRef={svgRef}
          ariaLabel={ariaLabel}
          instructions={t.chartInstructions}
          touchHint={t.touchHint}
        />
      )}
    </div>
  );
}

const BarLayers = memo(function BarLayers({
  geo,
  labels,
  id,
  fill,
  lineStroke,
  hasLine,
  hasPrev,
  shown,
  reduced,
  signature,
  tickFormat,
}: {
  geo: { g: FrameGeometry; barW: number; heights: number[]; line: string; prevLine: string };
  labels: BarTrendDatum[];
  id: string;
  fill: string;
  lineStroke: string;
  hasLine: boolean;
  hasPrev: boolean;
  shown: boolean;
  reduced: boolean;
  /** What the data looks like; compared with the last commit to tell new data (morph) from a resize (no morph). */
  signature: string;
  tickFormat: (n: number) => string;
}) {
  const changed = useDataChanged(signature);
  const { g, barW, heights, line, prevLine } = geo;
  const n = heights.length;
  const structure = String(n);
  const morph = reduced || !changed ? { duration: 0 } : trendSpring;

  // One progress value drives every bar: bar i runs over its own slice of it (a wave from the start).
  const progress = useMotionValue(reduced ? 1 : 0);
  const d = useMotionValue("");
  const anim = useRef({ from: heights.map(() => 0), to: heights, spread: 0.35, structure: "", played: false });
  const build = (p: number) => {
    const a = anim.current;
    const count = a.to.length;
    const r = Math.min(4, barW / 2);
    let out = "";
    for (let i = 0; i < count; i++) {
      const delay = count > 1 ? (i / (count - 1)) * a.spread : 0;
      const local = easeOutCubic(clamp((p - delay) / Math.max(0.0001, 1 - a.spread), 0, 1));
      const from = a.from[i] ?? 0;
      const h = Math.max(0, from + ((a.to[i] ?? 0) - from) * local);
      if (h > 0.25) out += barPath((g.xs[i] ?? 0) - barW / 2, g.innerH - h, barW, h, "top", r) + " ";
    }
    return out;
  };
  useMotionValueEvent(progress, "change", (p) => d.set(build(p)));

  useEffect(() => {
    const a = anim.current;
    // A new range, or bars that have not grown in yet (mounted off-screen): grow from the baseline.
    const fresh = a.structure !== structure || !a.played;
    // Start from what is on screen now (a tween can be interrupted), or from the baseline.
    const current = a.to.map((v, i) => {
      const delay = a.to.length > 1 ? (i / (a.to.length - 1)) * a.spread : 0;
      const local = easeOutCubic(clamp((progress.get() - delay) / Math.max(0.0001, 1 - a.spread), 0, 1));
      return (a.from[i] ?? 0) + (v - (a.from[i] ?? 0)) * local;
    });
    anim.current = {
      from: fresh ? heights.map(() => 0) : current,
      to: heights,
      spread: fresh ? 0.35 : 0.12,
      structure,
      played: true,
    };
    if (reduced || (!fresh && !changed)) {
      progress.jump(1);
      d.set(build(1));
      return;
    }
    if (!shown) {
      anim.current.played = false;
      progress.jump(0);
      d.set(build(0));
      return;
    }
    progress.jump(0);
    const controls = animate(progress, 1, { duration: fresh ? duration.slower : duration.slow, ease: ease.out });
    return () => controls.stop();
    // `build` reads the latest geometry through the closure of this render; `changed`, `d` and `progress` are read only when the geometry or visibility moves.
    // eslint-disable-next-line react-hooks/exhaustive-deps -- the tween restarts only when the bars, their structure, visibility, motion preference or geometry change: `build` is a new function every render, and `changed` (a boolean) is read as it was when the geometry last moved, on purpose, so it settling back to false does not restart the tween.
  }, [heights, structure, shown, reduced, barW, g.innerH, g.xs]);

  return (
    <>
      <defs>
        <linearGradient id={`${id}-bar`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor={fill} stopOpacity={1} />
          <stop offset="100%" stopColor={fill} stopOpacity={0.72} />
        </linearGradient>
        <WipeClip
          id={`${id}-wipe`}
          structure={structure}
          innerW={g.innerW}
          innerH={g.innerH}
          shown={shown}
          reduced={reduced}
        />
      </defs>
      <g aria-hidden transform={`translate(${g.left},${g.top})`}>
        <FrameAxes
          geo={g}
          labels={labels.map((dd) => dd.label)}
          structure={structure}
          morph={morph}
          tickFormat={tickFormat}
        />
        <motion.path d={d} fill={`url(#${id}-bar)`} />
        <g clipPath={`url(#${id}-wipe)`}>
          <AnimatePresence>
            {hasPrev && (
              <motion.path
                key={`p-${structure}`}
                fill="none"
                stroke="var(--sheen-fg-subtle)"
                strokeWidth={1.5}
                strokeDasharray="4 5"
                strokeLinecap="round"
                initial={{ opacity: 0, d: prevLine }}
                animate={{ opacity: 1, d: prevLine }}
                exit={{ opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }}
                transition={{ d: morph, opacity: { duration: duration.slow } }}
              />
            )}
          </AnimatePresence>
        </g>
        {hasLine && (
          <motion.path
            key={`l-${structure}`}
            fill="none"
            stroke={lineStroke}
            strokeWidth={2}
            strokeLinecap="round"
            strokeLinejoin="round"
            initial={{ pathLength: reduced ? 1 : 0, d: line }}
            animate={{ pathLength: shown ? 1 : 0, d: line }}
            transition={{
              pathLength: {
                duration: reduced ? 0 : duration.slower,
                ease: ease.out,
                delay: reduced ? 0 : duration.base,
              },
              d: morph,
            }}
          />
        )}
      </g>
    </>
  );
});

/* ====================================================================================
 * Ranges, demo data helpers
 * ==================================================================================== */

/** A dashboard time range: the last 24 hours, 7, 30 or 90 days, or 12 months. */
export type AnalyticsRange = "24h" | "7d" | "30d" | "90d" | "12m";

/** Every `AnalyticsRange`, shortest first (the order of the range picker). */
export const ANALYTICS_RANGES: readonly AnalyticsRange[] = ["24h", "7d", "30d", "90d", "12m"];

/** What a dashboard asks its loader for. */
export type AnalyticsQuery = {
  range: AnalyticsRange;
  /** Values of the active filter chips (empty = everything). */
  filters: readonly string[];
};

/**
 * Loads a dashboard's data. Return the data, or a promise of it (fetch from your API). The
 * signal aborts when the query changes before it settles. Throw (or reject) to show the error
 * state with a Retry button.
 */
export type AnalyticsLoader<T> = (query: AnalyticsQuery, signal: AbortSignal) => T | Promise<T>;

/** "auto" follows the loader; the others pin a state (handy for docs, tests and storybooks). */
export type AnalyticsStatus = "auto" | "loading" | "empty" | "error";

/** One point of a generated range: a stable `key`, its `Date`, a short axis `label` and a `long` tooltip label. */
export type RangePoint = {
  /** Stable identity of the point (ISO date or hour). */
  key: string;
  date: Date;
  /** Short axis label: "14:00", "Mon", "Oct 3", "Oct". */
  label: string;
  /** Long label for tooltips and tables: "Sat, Oct 31, 2:00 PM". */
  long: string;
};

/** How many points each range shows. Internal to the analytics kit and its demo data; safe to call on the server. */
export const RANGE_POINTS: Record<AnalyticsRange, number> = { "24h": 24, "7d": 7, "30d": 30, "90d": 90, "12m": 12 };

const dateFormatCache = new Map<string, Intl.DateTimeFormat>();

function dateFormat(locale: string | undefined, options: Intl.DateTimeFormatOptions) {
  const key = `${locale ?? ""}|${JSON.stringify(options)}`;
  let f = dateFormatCache.get(key);
  if (!f) {
    try {
      f = new Intl.DateTimeFormat(locale, { timeZone: "UTC", ...options });
    } catch {
      f = new Intl.DateTimeFormat("en", { timeZone: "UTC", ...options });
    }
    dateFormatCache.set(key, f);
  }
  return f;
}

/**
 * The time points of a range that ends at `end` (UTC ms): 24 hours, 7/30/90 days or 12 months. `end` is required, so a
 * chart never silently shows a hard-coded date: pass `Date.now()` for live data, or a fixed clock in tests and docs.
 */
export function rangePoints(range: AnalyticsRange, locale: string | undefined, end: number): RangePoint[] {
  const n = RANGE_POINTS[range];
  const out: RangePoint[] = [];
  const last = new Date(end);
  for (let i = n - 1; i >= 0; i--) {
    let date: Date;
    if (range === "24h") date = new Date(end - i * 3_600_000);
    else if (range === "12m") date = new Date(Date.UTC(last.getUTCFullYear(), last.getUTCMonth() - i, 1));
    else date = new Date(Date.UTC(last.getUTCFullYear(), last.getUTCMonth(), last.getUTCDate() - i));
    const label =
      range === "24h"
        ? dateFormat(locale, { hour: "numeric" }).format(date)
        : range === "7d"
          ? dateFormat(locale, { weekday: "short" }).format(date)
          : range === "12m"
            ? dateFormat(locale, { month: "short" }).format(date)
            : dateFormat(locale, { month: "short", day: "numeric" }).format(date);
    const long =
      range === "24h"
        ? dateFormat(locale, { weekday: "short", hour: "numeric", minute: "2-digit" }).format(date)
        : range === "12m"
          ? dateFormat(locale, { month: "long", year: "numeric" }).format(date)
          : dateFormat(locale, { weekday: "short", month: "short", day: "numeric" }).format(date);
    out.push({ key: date.toISOString(), date, label, long });
  }
  return out;
}

/** How many points a range has. */
export const rangeLength = (range: AnalyticsRange) => RANGE_POINTS[range];

export { exportCsv } from "../../lib/csv";

const isPlainObject = (v: unknown): v is Record<string, unknown> =>
  typeof v === "object" &&
  v !== null &&
  (Object.getPrototypeOf(v) === Object.prototype || Object.getPrototypeOf(v) === null);

/**
 * Structural sharing: returns `next`, but every part of it that deeply equals the same part of
 * `prev` is `prev`'s object. Memoised panels then skip whatever a new response didn't change.
 */
export function shareStructure<T>(prev: unknown, next: T): T {
  if (Object.is(prev, next)) return next;
  if (Array.isArray(prev) && Array.isArray(next)) {
    if (prev.length !== next.length) return next;
    let same = true;
    const out: unknown[] = [];
    // A loop (not map): `same` is assigned inside it, which flow analysis can follow.
    for (let i = 0; i < next.length; i++) {
      const shared = shareStructure<unknown>(prev[i], next[i]);
      if (shared !== prev[i]) same = false;
      out.push(shared);
    }
    return (same ? prev : out) as T;
  }
  if (isPlainObject(prev) && isPlainObject(next)) {
    const keys = Object.keys(next);
    let same = keys.length === Object.keys(prev).length;
    const out: Record<string, unknown> = {};
    for (const key of keys) {
      const shared = shareStructure(prev[key], next[key]);
      if (shared !== prev[key]) same = false;
      out[key] = shared;
    }
    return (same ? prev : out) as T;
  }
  if (prev instanceof Date && next instanceof Date && prev.getTime() === next.getTime()) return prev as T;
  return next;
}

/** Signed percent change from `previous` to `current`, as a ratio; null when undefined. */
export function changeRatio(current: number, previous: number | null | undefined) {
  if (
    previous === null ||
    previous === undefined ||
    !Number.isFinite(previous) ||
    previous === 0 ||
    !Number.isFinite(current)
  )
    return null;
  return (current - previous) / Math.abs(previous);
}

const percentCache = new Map<string, Intl.NumberFormat>();

/** "+12.4%", "−3%" in a locale (typographic minus). */
export function formatChange(ratio: number, locale?: string) {
  const key = locale ?? "";
  let f = percentCache.get(key);
  if (!f) {
    f = new Intl.NumberFormat(locale ?? "en", {
      style: "percent",
      minimumFractionDigits: 0,
      maximumFractionDigits: 1,
      signDisplay: "exceptZero",
    });
    percentCache.set(key, f);
  }
  return f.format(ratio).replace("-", "−");
}

/* ====================================================================================
 * Rolling numbers
 * ==================================================================================== */

const numberFormats = new Map<string, Intl.NumberFormat>();

function numberFormat(locale: string | undefined, options: Intl.NumberFormatOptions | undefined) {
  const key = `${locale ?? ""}|${JSON.stringify(options ?? {})}`;
  let f = numberFormats.get(key);
  if (!f) {
    f = new Intl.NumberFormat(locale, options);
    numberFormats.set(key, f);
  }
  return f;
}

/** A number formatter from either form `format` takes. */
export function resolveFormat(
  format: ((n: number) => string) | Intl.NumberFormatOptions | undefined,
  locale?: string,
): (n: number) => string {
  if (typeof format === "function") return format;
  const f = numberFormat(locale, format);
  return (n) => f.format(n);
}

"use client";

import type { ComponentProps } from "react";
import { createContext, useEffect, useState, useSyncExternalStore, type RefObject } from "react";

import { observeIntersection } from "../../hooks/use-intersection";
import { cn } from "../../lib/cn";

/* ====================================================================================
 * Shell (header + controls)
 * ==================================================================================== */

/**
 * Heading level of the panels: one below the dashboard title (set by AnalyticsShell).
 *
 * @internal Not exported from the package barrel, so its example is not type-checked against `@sheenui/theme`.
 *
 * @example
 * ```tsx
 * import { useContext } from "react";
 * import { PanelHeadingContext } from "./glass";
 *
 * export function Example() {
 *   const level = useContext(PanelHeadingContext); // "h2" | "h3" | "h4" | "p"
 *   return <p>{level}</p>;
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export const PanelHeadingContext = createContext<"h2" | "h3" | "h4" | "p">("h3");

/** Controls inside a glass surface sit on its blur already: drop their own backdrop-filter. */
export const noBlur = "[-webkit-backdrop-filter:none] [backdrop-filter:none]";

/**
 * Frosted solid surface for a panel when the dashboard runs flat glass (`data-glass-budget`):
 * same rim, sheen and shadow, a denser fill, no backdrop-filter.
 */
export const flatCard =
  "[[data-glass-budget=flat]_&]:[backdrop-filter:none]! [[data-glass-budget=flat]_&]:[-webkit-backdrop-filter:none]! [[data-glass-budget=flat]_&]:bg-sheen-surface/85";

/** Glass budget of a dashboard: `"auto"` measures frames and goes flat when the device cannot keep up, `"full"` always uses real glass, `"flat"` always uses frosted solid panels. */
export type AnalyticsGlass = "auto" | "full" | "flat";

/**
 * The glass budget `AnalyticsShell` resolved (`"full"` or `"flat"`), for the surfaces inside it.
 * Read it with `useContext` to drop your own backdrop blur when the dashboard runs flat; the
 * default is `"full"` outside a shell.
 *
 * Accessibility and keyboard: none of its own. Glass: `"flat"` means frosted solid panels with no
 * `backdrop-filter` (weak device, Lite glass, Save-Data, or measured dropped frames).
 *
 * @example
 * ```tsx
 * import { useContext, type Context } from "react";
 * import { Badge } from "@sheenui/theme";
 *
 * // Placeholder: an internal context of the analytics kit, not part of the package entry.
 * declare const GlassBudgetContext: Context<"full" | "flat">;
 *
 * function Chip() {
 *   const budget = useContext(GlassBudgetContext);
 *   return <Badge className={budget === "flat" ? "bg-sheen-surface" : "backdrop-blur-md"}>chip</Badge>;
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export const GlassBudgetContext = createContext<"full" | "flat">("full");

const GLASS_KEY = "sheen:dashboard-glass";

type DeviceHints = Navigator & { deviceMemory?: number; connection?: { saveData?: boolean } };

/** Weak device or a data saver: start with flat panels. */
function weakDevice() {
  if (typeof navigator === "undefined") return false;
  const nav = navigator as DeviceHints;
  return (
    (nav.deviceMemory !== undefined && nav.deviceMemory <= 4) ||
    (nav.hardwareConcurrency > 0 && nav.hardwareConcurrency <= 4) ||
    nav.connection?.saveData === true
  );
}

/** `useSyncExternalStore` subscribe for values that only change with a reload or a re-render. */
function subscribeNever() {
  return () => undefined;
}

function storedFlat() {
  try {
    return sessionStorage.getItem(GLASS_KEY) === "flat";
  } catch {
    return false;
  }
}

/** Whether the dashboard should start with flat panels (see `useAdaptiveGlass`). */
function startsFlat() {
  return weakDevice() || storedFlat() || document.documentElement.dataset.glass === "lite";
}

/**
 * Glass budget for a whole dashboard. Large panels are the most expensive glass on a page (each
 * re-blurs its backdrop on every scrolled frame), so in "auto" they stay real glass only while the
 * device keeps up: on a weak device (memory, cores, Save-Data), with lite glass on, or once frames
 * drop while the dashboard scrolls or animates, they switch to a frosted solid surface (no
 * backdrop-filter) for the rest of the session. The header keeps its blur.
 *
 * Parameters: `ref` (`RefObject<HTMLElement | null>`, the dashboard root whose frames are watched) and
 * `mode` (`"auto" | "full" | "flat"`, default `"auto"`; the other two force a budget). Returns
 * `"full"` or `"flat"`: put it in `data-glass-budget` on the root and in `GlassBudgetContext`.
 * Keyboard and accessibility: none of its own; flat panels keep the same contrast and structure.
 * Motion and glass: it only samples frames while the pointer moves or the page scrolls over the
 * dashboard, so an idle dashboard costs nothing; the choice sticks for the session.
 *
 * @example
 * ```tsx
 * import { useRef } from "react";
 * import { useAdaptiveGlass } from "@sheenui/theme";
 *
 * function Frame({ children }: { children: React.ReactNode }) {
 *   const ref = useRef<HTMLElement>(null);
 *   const budget = useAdaptiveGlass(ref); // "full" until frames drop
 *   return <section ref={ref} data-glass-budget={budget}>{children}</section>;
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function useAdaptiveGlass(ref: RefObject<HTMLElement | null>, mode: AnalyticsGlass = "auto") {
  const [flat, setFlat] = useState(false);
  // Known before any frame is measured: a weak device, a data saver, Lite glass, or a flat verdict from earlier in the session.
  const flatFromStart = useSyncExternalStore(subscribeNever, startsFlat, () => false);
  useEffect(() => {
    if (mode !== "auto" || flatFromStart) return;
    const root = ref.current;
    if (!root) return;
    // Watch frames only while something is moving: a scroll, the pointer over the dashboard.
    let raf = 0;
    let until = 0;
    let last = 0;
    let frames = 0;
    let slow = 0;
    let badWindows = 0;
    let windowStart = 0;
    const tick = (t: number) => {
      if (last) {
        frames += 1;
        if (t - last > 25) slow += 1;
      } else windowStart = t;
      last = t;
      if (t - windowStart >= 1000) {
        // A window where more than 1 in 8 frames missed its slot: the device isn't keeping up.
        badWindows = frames >= 20 && slow / frames > 0.125 ? badWindows + 1 : 0;
        frames = slow = 0;
        windowStart = t;
        if (badWindows >= 2) {
          try {
            sessionStorage.setItem(GLASS_KEY, "flat");
          } catch {
            /* storage blocked: flat for this page only */
          }
          setFlat(true);
          return;
        }
      }
      if (t < until) raf = requestAnimationFrame(tick);
      else {
        raf = 0;
        last = 0;
      }
    };
    const wake = () => {
      until = performance.now() + 1500;
      if (!raf) raf = requestAnimationFrame(tick);
    };
    const stopObserving = observeIntersection(root, (entry) => {
      if (entry.isIntersecting) window.addEventListener("scroll", wake, { passive: true });
      else window.removeEventListener("scroll", wake);
    });
    root.addEventListener("pointermove", wake, { passive: true });
    return () => {
      stopObserving();
      window.removeEventListener("scroll", wake);
      root.removeEventListener("pointermove", wake);
      if (raf) cancelAnimationFrame(raf);
    };
  }, [ref, mode, flatFromStart]);
  return mode === "flat" || (mode === "auto" && (flat || flatFromStart)) ? "flat" : "full";
}

/**
 * Soft, static colour light behind a dashboard so its glass always has something to refract.
 * Plain gradients: no animation, no filter, painted once. AnalyticsShell renders it by default.
 *
 * Props: `className` (`string`, extra classes for the absolutely positioned layer).
 * Accessibility: `aria-hidden`, purely decorative; hidden in forced-colors mode. Keyboard: none.
 * Glass and motion: four static radial gradients from the `--sheen-blob-*` tokens (so the Style
 * presets and dark mode recolour it); no animation, no filter, painted once.
 *
 * @example
 * ```tsx
 * import { DashboardBackdrop } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <div className="relative isolate rounded-3xl p-6">
 *       <DashboardBackdrop />
 *       <h2>Glass sits on this light</h2>
 *     </div>
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function DashboardBackdrop({ className }: { className?: string }) {
  return (
    <div
      aria-hidden
      data-slot="dashboard-backdrop"
      className={cn(
        "pointer-events-none absolute inset-0 rounded-[inherit]",
        "[background:radial-gradient(42%_36%_at_12%_6%,color-mix(in_oklab,var(--sheen-blob-1)_70%,transparent),transparent_72%),radial-gradient(36%_30%_at_92%_28%,color-mix(in_oklab,var(--sheen-blob-2)_60%,transparent),transparent_72%),radial-gradient(40%_32%_at_28%_72%,color-mix(in_oklab,var(--sheen-blob-3)_55%,transparent),transparent_72%),radial-gradient(34%_28%_at_84%_92%,color-mix(in_oklab,var(--sheen-blob-4)_55%,transparent),transparent_72%)]",
        "forced-colors:hidden",
        className,
      )}
    />
  );
}

/** Alias of `AnalyticsGlass`. */
export type DashboardGlass = AnalyticsGlass;

/** Props of {@link DashboardBackdrop}. Soft, static colour light behind a dashboard so its glass always has something to refract. */
export type DashboardBackdropProps = ComponentProps<typeof DashboardBackdrop>;

"use client";

import type { ComponentProps } from "react";
import { useControllable } from "../../hooks/use-controllable";
import {
  startTransition,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import { useLatest } from "../../hooks/use-latest";

import { isScrolling } from "../../motion/beat";
import { useLoopPlayback } from "../../motion/gate";
import { type AnalyticsLoader, type AnalyticsRange, type AnalyticsStatus, shareStructure } from "./data";

/** Where `useDashboardData` is: first load or reload (`loading`), data on screen (`ready`), or the last load failed (`error`). */
export type DashboardStatus = "loading" | "ready" | "error";

type DataState<Q, D> = { data: D | null; error: unknown; key: string | null; query: Q | null };

/**
 * The one data-loading hook of every dashboard. It loads data for `query` whenever `queryKey` changes (a dashboard's
 * query is not always just range + filters). The previous data stays on screen while the next loads (the frame never
 * flashes empty), stale responses are dropped and their request is aborted, errors keep the old data for a retry, and
 * `update` evolves the data in place (live ticks) without a loading state. `loading` is derived (the loaded key differs
 * from the asked one), so a click never pays for an extra render, and `retry` / `update` keep their identity. New data
 * is committed in a transition, so React renders big charts in slices. `query` is what the data on screen answers.
 *
 * Parameters: `load` (`(query: Q, signal: AbortSignal) => D | Promise<D>`; the `signal` aborts when the key changes or the
 * component unmounts), `query` (`Q`, the current request) and `queryKey` (`string`, a stable key of `query`: the load
 * re-runs when it changes). Returns `{ data, status, loading, error, query, retry, update }`: `data` is `D | null`,
 * `status` a `DashboardStatus`, `retry()` reloads after an error and `update(fn)` patches the data in place.
 * Accessibility, keyboard, glass and motion: none of its own (a data hook, no DOM); show `status` with an
 * `AnalyticsState` or a live region.
 *
 * @example
 * ```tsx
 * import { useDashboardData } from "@sheenui/theme";
 *
 * function Orders({ team }: { team: string }) {
 *   const { data, status, retry } = useDashboardData(
 *     async (q: { team: string }, signal) => (await fetch(`/api/orders?team=${q.team}`, { signal })).json() as Promise<number[]>,
 *     { team },
 *     team,
 *   );
 *   if (status === "error") return <button type="button" onClick={retry}>Retry</button>;
 *   return <p>{data ? data.length : "Loading"}</p>;
 * }
 * ```
 *
 * @see /dashboards/product
 */
export function useDashboardData<Q, D>(
  load: (query: Q, signal: AbortSignal) => D | Promise<D>,
  query: Q,
  queryKey: string,
) {
  const [state, setState] = useState<DataState<Q, D>>({ data: null, error: null, key: null, query: null });
  const [attempt, setAttempt] = useState(0);
  const latestRef = useLatest({ load, query });
  const key = `${queryKey}\u0000${attempt}`;

  useEffect(() => {
    // One AbortSignal per request: a newer query (or unmounting) aborts the one still in flight.
    const controller = new AbortController();
    Promise.resolve()
      .then(() => {
        const q = latestRef.current.query;
        return Promise.resolve(latestRef.current.load(q, controller.signal)).then((data) => [data, q] as const);
      })
      .then(
        ([data, q]) => {
          if (controller.signal.aborted) return;
          // A transition: React renders the new charts in slices instead of one long task.
          startTransition(() => setState((s) => ({ data: shareStructure(s.data, data), error: null, key, query: q })));
        },
        (error: unknown) => {
          if (controller.signal.aborted) return;
          startTransition(() => setState((s) => ({ ...s, error: error ?? new Error("Failed to load"), key })));
        },
      );
    return () => controller.abort();
  }, [key, latestRef]);

  const update = useCallback((patch: (prev: D) => D) => {
    startTransition(() => setState((s) => (s.data === null || s.error ? s : { ...s, data: patch(s.data) })));
  }, []);
  const retry = useCallback(() => setAttempt((n) => n + 1), []);
  const loading = state.key !== key;
  const failed = !loading && Boolean(state.error);
  const status: DashboardStatus = failed ? "error" : loading ? "loading" : "ready";
  /** `query` is the one the data on screen answers (it lags the asked one while loading). */
  return { data: state.data, query: state.query, error: loading ? null : state.error, status, loading, update, retry };
}

/**
 * Hands `value` on after `index × step` ms, in a transition: when a dashboard's data changes,
 * its panels take the new data one after another, and each re-render is its own small task.
 *
 * Parameters: `value` (`T`, the latest value), `index` (`number`, this panel's place in the
 * order), `step` (`number`, default 45, milliseconds between panels). Returns the value to show.
 * Accessibility: none of its own (the delay is under half a second even for twelve panels).
 * Motion: no animation; it only staggers when the new data renders, so reduced motion needs no
 * special case.
 *
 * @example
 * ```tsx
 * import { useCascade } from "@sheenui/theme";
 *
 * function Panel({ rows, index }: { rows: number[]; index: number }) {
 *   const shown = useCascade(rows, index); // later panels update a little later
 *   return <p>{shown.length} rows</p>;
 * }
 * ```
 *
 * @see /dashboards/crypto-dashboard
 */
export function useCascade<T>(value: T, index: number, step = 45) {
  const [shown, setShown] = useState(value);
  useEffect(() => {
    if (Object.is(value, shown)) return;
    const t = window.setTimeout(() => startTransition(() => setShown(value)), index * step);
    return () => window.clearTimeout(t);
  }, [value, shown, index, step]);
  return shown;
}

/**
 * Render-prop form of `useCascade`: only this wrapper re-renders when its turn comes, so the
 * parent (and its other panels) stay untouched.
 *
 * Props: `value` (`T`, required, the latest value), `index` (`number`, required, the panel's
 * place in the order), `step` (`number`, default 45, milliseconds between panels), `children`
 * (`(value: T) => ReactNode`, required, renders with the delayed value).
 * Accessibility and keyboard: none of its own; it renders no element. Glass and motion: none; it
 * only staggers when data renders.
 *
 * @example
 * ```tsx
 * import { Cascade } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <Cascade value={{ visitors: 1280 }} index={2}>
 *       {(data) => <p>{data.visitors} visitors</p>}
 *     </Cascade>
 *   );
 * }
 * ```
 *
 * @see /dashboards/crypto-dashboard
 */
export function Cascade<T>({
  value,
  index,
  step = 45,
  children,
}: {
  /** The data to hand to the children; panel number `index` receives it a beat after the one before. */
  value: T;
  /** Position of this panel in the cascade (0 is first). */
  index: number;
  /** Milliseconds between one panel receiving new data and the next. */
  step?: number;
  children: (value: T) => ReactNode;
}) {
  const shown = useCascade(value, index, step);
  return <>{children(shown)}</>;
}

/* ====================================================================================
 * Data + live hooks
 * ==================================================================================== */

/**
 * Calls `onTick` every `interval` ms while `enabled`, but only while `ref` is on screen and the
 * tab is visible: a live dashboard nobody is looking at costs nothing. Returns whether it runs.
 *
 * Parameters: `enabled` (`boolean`), `onTick` (`(tick: number) => void`, the tick count starts at
 * 1; the latest function is always used), and an options object: `ref` (`RefObject<Element | null>`,
 * required, the element whose visibility gates the ticks) and `interval` (`number`, default 2400,
 * milliseconds, never below 250).
 * Accessibility: pair live data with a pause control (WCAG 2.2.2); `enabled` is that switch.
 * Motion: it only schedules updates; it pauses off-screen and in hidden tabs.
 *
 * @example
 * ```tsx
 * import { useRef, useState } from "react";
 * import { useLiveTicker } from "@sheenui/theme";
 *
 * function LiveCount() {
 *   const ref = useRef<HTMLDivElement>(null);
 *   const [n, setN] = useState(0);
 *   useLiveTicker(true, (tick) => setN(tick), { ref, interval: 1000 });
 *   return <div ref={ref}>{n} ticks</div>;
 * }
 * ```
 *
 * @see /dashboards/product
 */
export function useLiveTicker(
  enabled: boolean,
  onTick: (tick: number) => void,
  { interval = 2400, ref }: { interval?: number; ref: RefObject<Element | null> },
) {
  const callbackRef = useLatest(onTick);
  const running = useLoopPlayback(ref, { paused: !enabled, margin: "0px", respectReducedMotion: false });
  useEffect(() => {
    if (!running) return;
    let tick = 0;
    // A tick that lands mid-scroll would rewrite chart paths in the frame being scrolled: skip it (the next one is at most `interval` away).
    const timer = window.setInterval(
      () => {
        if (!isScrolling()) callbackRef.current(++tick);
      },
      Math.max(250, interval),
    );
    return () => window.clearInterval(timer);
  }, [running, interval, callbackRef]);
  return running;
}

/* ====================================================================================
 * One hook for a whole dashboard's state
 * ==================================================================================== */

/** The state props every dashboard template takes (controlled or not). */
export type AnalyticsDashboardStateProps<T> = {
  /**
   * Loads the data for a range + filters (sync or async). Required: no dashboard falls back to fake data. The demo
   * loaders live in `@sheenui/theme/demo-data`, which the package root does not export.
   */
  load: AnalyticsLoader<T>;
  /** Evolves the data on each live tick (omit for no live updates). Return a new object; unchanged parts keep their identity. */
  liveStep?: (prev: T, tick: number) => T;
  /** Sets the active range when controlled. Pair with `onRangeChange`. */
  range?: AnalyticsRange;
  /**
   * The range at first when `range` is not controlled (`AnalyticsRange`); each dashboard picks its own.
   *
   * @default per dashboard
   */
  defaultRange?: AnalyticsRange;
  /** Called when the range changes. */
  onRangeChange?: (range: AnalyticsRange) => void;
  /** Values of the active filter chips (controlled). */
  activeFilters?: string[];
  /** The filters on at first when `activeFilters` is not controlled (`string[]`, default none). */
  defaultFilters?: string[];
  /** Called when the filter chips change. */
  onFiltersChange?: (filters: string[]) => void;
  /** Simulated live updates. The Live toggle pauses them (WCAG 2.2.2). */
  live?: boolean;
  /**
   * Whether live updates are on at first when `live` is not controlled (`boolean`); each dashboard picks its own.
   *
   * @default per dashboard
   */
  defaultLive?: boolean;
  /** Called when the Live toggle changes. */
  onLiveChange?: (live: boolean) => void;
  /** Show the previous period (dashed lines, "vs" values). */
  compare?: boolean;
  /**
   * Whether the comparison is on at first when `compare` is not controlled (`boolean`); each dashboard picks its own.
   *
   * @default per dashboard
   */
  defaultCompare?: boolean;
  /** Called when the Compare toggle changes. */
  onCompareChange?: (compare: boolean) => void;
  /**
   * Pin a state (docs, tests); "auto" follows the loader.
   * @default "auto"
   */
  status?: AnalyticsStatus;
};

/**
 * Wires a dashboard: controllable range / filters / live / compare, the loader, live ticks
 * (paused off-screen and in hidden tabs) and the resulting status. Attach `rootRef` to the root.
 * It is what every ready-made dashboard (web, SaaS, e-commerce, product, finance) is built on;
 * use it to build your own.
 *
 * Parameters: `props` (`AnalyticsDashboardStateProps<T>`, the controlled / default / callback
 * trios plus the required `load`, an optional `liveStep` and a pinned `status`) and an options object:
 * `liveStep` (`(prev, tick) => next`, a default for `props.liveStep`; makes the data live),
 * `liveInterval` (`number`, default 2400 ms), `defaults` (`{ range, live, compare }`) and
 * `isEmpty` (`(data) => boolean`). Returns the data result plus `status`
 * (`"ready" | "loading" | "empty" | "error"`), `ready`, `busy`, `range` / `setRange`,
 * `live` / `setLive`, `compare` / `setCompare`, `filters` / `setFilters`, `running` and `rootRef`.
 * Accessibility: live updates must stay pausable (WCAG 2.2.2): bind `live` to a toggle, as
 * `AnalyticsShell` does. Keyboard and glass: none of its own. Motion: ticks pause off-screen and
 * in hidden tabs.
 *
 * @example
 * ```tsx
 * import { useAnalyticsDashboard, type AnalyticsDashboardStateProps } from "@sheenui/theme";
 *
 * function MyDashboard(props: AnalyticsDashboardStateProps<number[]>) {
 *   const d = useAnalyticsDashboard(props, {
 *     defaults: { range: "7d", live: false, compare: false },
 *     isEmpty: (data) => data.length === 0,
 *   });
 *   return <div ref={d.rootRef}>{d.status === "ready" ? d.data?.join(", ") : d.status}</div>;
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function useAnalyticsDashboard<T>(
  props: AnalyticsDashboardStateProps<T>,
  {
    liveStep: defaultLiveStep,
    liveInterval = 2400,
    defaults,
    isEmpty,
  }: {
    liveStep?: (prev: T, tick: number) => T;
    liveInterval?: number;
    defaults: { range: AnalyticsRange; live: boolean; compare: boolean };
    isEmpty: (data: T) => boolean;
  },
) {
  const status = props.status ?? "auto";
  const liveStep = props.liveStep ?? defaultLiveStep;
  const [range, setRange] = useControllable(props.range, props.defaultRange ?? defaults.range, props.onRangeChange);
  const [live, setLive] = useControllable(props.live, props.defaultLive ?? defaults.live, props.onLiveChange);
  const [compare, setCompare] = useControllable(
    props.compare,
    props.defaultCompare ?? defaults.compare,
    props.onCompareChange,
  );
  const [filters, setFilters] = useControllable<string[]>(
    props.activeFilters,
    props.defaultFilters ?? EMPTY,
    props.onFiltersChange,
  );
  const rootRef = useRef<HTMLDivElement>(null);
  const query = useMemo(() => ({ range, filters }), [range, filters]);
  const filtersKey = filters.join("\u0001");
  const result = useDashboardData(props.load, query, `${range}\u0002${filtersKey}`);
  const { data, error, update } = result;

  const stepRef = useLatest(liveStep);
  const tick = useCallback(
    (n: number) => update((prev) => (stepRef.current ? stepRef.current(prev, n) : prev)),
    [update, stepRef],
  );
  const running = useLiveTicker(Boolean(liveStep) && live && status === "auto" && data !== null, tick, {
    ref: rootRef,
    interval: liveInterval,
  });

  const shown: "ready" | "loading" | "empty" | "error" =
    status === "loading"
      ? "loading"
      : status === "empty"
        ? "empty"
        : status === "error"
          ? "error"
          : error
            ? "error"
            : data && isEmpty(data)
              ? "empty"
              : data
                ? "ready"
                : "loading";
  return {
    ...result,
    status: shown,
    ready: shown === "ready",
    busy: status === "auto" && result.loading && data !== null,
    range,
    setRange,
    live,
    setLive,
    compare,
    setCompare,
    filters,
    setFilters,
    running,
    rootRef,
  };
}

const EMPTY: string[] = [];

/** Props of {@link Cascade}. Render-prop form of `useCascade`: only this wrapper re-renders when its turn comes, so the parent (and its other panels) stay untouched. */
export type CascadeProps = ComponentProps<typeof Cascade>;

