import { useLoopPlayback } from "../../motion/gate";
import {
  type AnalyticsGlass,
  DashboardBackdrop,
  GlassBudgetContext,
  PanelHeadingContext,
  noBlur,
  useAdaptiveGlass,
} from "./glass";
import { useMergedRef } from "../../lib/form";

/** A filter chip of `AnalyticsShell`: `value` is what `activeFilters` holds, `label` is the chip text. */
export type AnalyticsFilter = { value: string; label: string };

/** Props of `AnalyticsShell`. The state props (`range`, `live`, `compare`, `activeFilters`…) come straight from `useAnalyticsDashboard`. */
export type AnalyticsShellProps = {
  /** The root element (e.g. for useLiveTicker). */
  ref?: Ref<HTMLElement>;
  /** The dashboard's title (`ReactNode`, required), rendered as the heading `headingLevel`. */
  title: ReactNode;
  /** Shows a line under the title (`ReactNode`). */
  subtitle?: ReactNode;
  /** A small mark before the title. */
  icon?: ReactNode;
  /** Shown beside the title (e.g. a live visitors pill). */
  status?: ReactNode;
  /** The `id` of the title heading (`string`, required): the section is `aria-labelledby` it. */
  headingId: string;
  /** Heading level of the dashboard title (1 to 6), to fit the page outline, or `"none"` for a paragraph with no heading role (panel titles follow). Default 2. */
  headingLevel?: HeadingLevelOption;
  /** Sets the selected range (`AnalyticsRange`, required). */
  range: AnalyticsRange;
  /** Called when another range is picked (required). */
  onRangeChange: (range: AnalyticsRange) => void;
  /** The ranges offered (`readonly AnalyticsRange[]`, default all five: 24h, 7d, 30d, 90d, 12m). */
  ranges?: readonly AnalyticsRange[];
  /** Filter chips shown next to the range control; none when omitted or empty. */
  filters?: readonly AnalyticsFilter[];
  /** The `value`s of the chips that are on (required). */
  activeFilters: readonly string[];
  /** Called with the new list of active chip values (required). */
  onFiltersChange: (filters: string[]) => void;
  /** Whether live updates run (required); the Live toggle must stay (WCAG 2.2.2). */
  live: boolean;
  /** Called when the Live toggle is pressed (required). */
  onLiveChange: (live: boolean) => void;
  /** Whether the previous period is drawn (required). */
  compare: boolean;
  /** Called when the Compare toggle is pressed (required). */
  onCompareChange: (compare: boolean) => void;
  /** Called by the Export button. Omit to hide it. */
  onExport?: () => void;
  /** Keep Export disabled (`boolean`, default `false`), e.g. until the first data arrives: the button is always there, so the toolbar never shifts. */
  exportDisabled?: boolean;
  /** New data is on its way (`boolean`, default `false`): panels dim and scan, `aria-busy` is set, and "Loading" / "Updated" are announced once each. */
  loading?: boolean;
  /**
   * Glass on the panels: "auto" (default) keeps real glass while the device keeps up and falls
   * back to a frosted solid surface on weak devices or when frames drop; "full" / "flat" force one.
   */
  glass?: AnalyticsGlass;
  /** Draws a soft colour light behind the dashboard. Default true. */
  backdrop?: boolean;
  /** Every string of the shell and its panels (`AnalyticsLabels`, required): start from `defaultAnalyticsLabels`. */
  labels: AnalyticsLabels;
  /** The dashboard body, usually an `AnalyticsGrid` of `AnalyticsPanel`s. */
  children: ReactNode;
  /** Adds extra classes to the root `<section>` (`string`). */
  className?: string;
};

/**
 * The frame of a dashboard: a container-query root (the grid adapts to the space it gets, not to
 * the window) with a glass header. Its controls drop their own blur: one backdrop-filter, not six.
 * Use it to build a dashboard of your own; the five ready-made ones (web, SaaS, e-commerce,
 * product, finance) are built on it.
 *
 * Props (see `AnalyticsShellProps`): `title`, `headingId`, `range` / `onRangeChange`,
 * `activeFilters` / `onFiltersChange`, `live` / `onLiveChange`, `compare` / `onCompareChange` and
 * `labels` are required; `subtitle`, `icon`, `status`, `headingLevel` (`2`), `ranges`, `filters`,
 * `onExport`, `loading` (`false`), `glass` (`"auto"`), `backdrop` (`true`), `ref` and `className`
 * are optional.
 *
 * Keyboard: Tab reaches the range control (arrow keys move inside it), the filter chips (Space
 * or Enter toggles, `aria-pressed`), the Live and Compare toggles and Export. Pressed states use
 * a shape cue as well as colour.
 * Accessibility: a named `<section role="group">` (labelled by the title; not a landmark, so a dashboard can appear twice on a page) with `aria-busy` while loading; two polite live regions
 * announce loads once each; panels get a heading one level below the title.
 * Glass and motion: the header is the one `glass-3` surface that keeps its blur; panels follow
 * the adaptive glass budget (frosted solid when the device cannot keep up). The soft backdrop is
 * static; reduced motion removes the load scan and the entrance rise.
 *
 * @example
 * ```tsx
 * import { useState } from "react";
 * import { AnalyticsGrid, AnalyticsPanel, AnalyticsShell, defaultAnalyticsLabels, type AnalyticsRange } from "@sheenui/theme";
 *
 * function Traffic() {
 *   const [range, setRange] = useState<AnalyticsRange>("30d");
 *   const [live, setLive] = useState(false);
 *   const [compare, setCompare] = useState(false);
 *   const [filters, setFilters] = useState<string[]>([]);
 *   return (
 *     <AnalyticsShell
 *       title="Traffic"
 *       headingId="traffic-title"
 *       range={range}
 *       onRangeChange={setRange}
 *       activeFilters={filters}
 *       onFiltersChange={setFilters}
 *       live={live}
 *       onLiveChange={setLive}
 *       compare={compare}
 *       onCompareChange={setCompare}
 *       labels={defaultAnalyticsLabels}
 *     >
 *       <AnalyticsGrid>
 *         <AnalyticsPanel title="Visitors" span={{ lg: 2 }} minHeight={240} ready labels={defaultAnalyticsLabels}>
 *           <p>Your chart or table goes here.</p>
 *         </AnalyticsPanel>
 *       </AnalyticsGrid>
 *     </AnalyticsShell>
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function AnalyticsShell({
  ref,
  title,
  subtitle,
  icon,
  status,
  headingId,
  headingLevel = 2,
  range,
  onRangeChange,
  ranges = ANALYTICS_RANGES,
  filters,
  activeFilters,
  onFiltersChange,
  live,
  onLiveChange,
  compare,
  onCompareChange,
  onExport,
  exportDisabled = false,
  loading = false,
  glass = "auto",
  backdrop = true,
  labels,
  children,
  className,
}: AnalyticsShellProps) {
  const Heading = HEADING_TAGS[headingBelow(headingLevel, 0)];
  const reduced = useSheenReducedMotion();
  const rootRef = useRef<HTMLElement>(null);
  const setRoot = useMergedRef(rootRef, ref);
  const glassBudget = useAdaptiveGlass(rootRef, glass);
  const [exported, setExported] = useState(false);
  const exportTimer = useRef<number | undefined>(undefined);
  useEffect(() => () => window.clearTimeout(exportTimer.current), []);

  // Announce loads once each (not every live tick): "Loading new data…" → "Dashboard updated".
  const [announce, setAnnounce] = useState("");
  const wasLoading = useRef(loading);
  useEffect(() => {
    if (loading && !wasLoading.current) setAnnounce(labels.loading);
    else if (!loading && wasLoading.current) setAnnounce(labels.loaded);
    wasLoading.current = loading;
  }, [loading, labels.loading, labels.loaded]);

  return (
    <section
      ref={setRoot}
      role="group"
      data-slot="analytics-shell"
      aria-labelledby={headingId}
      aria-busy={loading || undefined}
      // Panels dim and show their scan line from this attribute (CSS): loading never re-renders them.
      data-busy={loading || undefined}
      data-glass-budget={glassBudget}
      className={cn(
        "group/dash @container relative flex w-full min-w-0 flex-col gap-4 @5xl:gap-5",
        // Glass budget: blur cost grows with radius × area, and these panels are large. Over the soft
        // backdrop a 14px blur reads exactly like 20px; phones go lighter still.
        "[--sheen-glass-2-blur:14px] [--sheen-glass-3-blur:24px] max-sm:[--sheen-glass-2-blur:10px] max-sm:[--sheen-glass-3-blur:16px]",
        className,
      )}
    >
      <NoScriptReveal />
      {backdrop && <DashboardBackdrop />}
      <header role="none" className="glass-3 flex min-w-0 flex-col gap-4 rounded-sheen-xl p-4 @2xl:p-5">
        <div className="flex min-w-0 flex-wrap items-start justify-between gap-x-4 gap-y-3">
          <div className="flex min-w-0 items-center gap-3">
            {icon && (
              <span
                aria-hidden
                className="sheen-fill grid size-10 shrink-0 place-items-center rounded-sheen-md text-sheen-accent-fg shadow-(--sheen-accent-fill-shadow) [background-image:var(--sheen-accent-fill)]"
              >
                {icon}
              </span>
            )}
            <div className="min-w-0">
              <div className="flex min-w-0 flex-wrap items-center gap-x-2.5 gap-y-1">
                <Heading
                  id={headingId}
                  className="text-lg leading-tight font-semibold tracking-tight text-balance @2xl:text-xl"
                >
                  {/* bdi: a name like "Lumen & Co." keeps its punctuation in place on right-to-left pages. */}
                  <bdi>{title}</bdi>
                </Heading>
                {status}
              </div>
              {subtitle && <p className="mt-0.5 text-sm text-pretty text-sheen-fg-muted">{subtitle}</p>}
            </div>
          </div>
          <div className="flex flex-wrap items-center gap-2">
            <HeaderToggles
              live={live}
              compare={compare}
              onLiveChange={onLiveChange}
              onCompareChange={onCompareChange}
              labels={labels}
            />
            {onExport && (
              <Button
                variant="ghost"
                size="sm"
                // Mounted from the first paint (a dashboard passes its handler before its data arrives) so the
                // toolbar keeps its width; there is nothing to export while the data loads.
                disabled={loading || exportDisabled}
                className="h-9 rounded-sheen-full border border-sheen-border px-3.5 text-sm any-pointer-coarse:h-11"
                leading={exported ? <CheckIcon className="size-4 text-sheen-success-text" /> : <DownloadIcon />}
                onClick={() => {
                  onExport();
                  setExported(true);
                  window.clearTimeout(exportTimer.current);
                  exportTimer.current = window.setTimeout(() => setExported(false), 2200);
                }}
              >
                {labels.export}
              </Button>
            )}
          </div>
        </div>

        <div className="flex min-w-0 flex-wrap items-center justify-between gap-3">
          <RangeControl range={range} ranges={ranges} onRangeChange={onRangeChange} labels={labels} />
          {filters && filters.length > 0 && (
            <FilterChips filters={filters} active={activeFilters} onChange={onFiltersChange} label={labels.filters} />
          )}
        </div>
        {/* Busy scan: a thin light runs along the header's bottom edge while data loads. */}
        <AnimatePresence>
          {loading && (
            <motion.span
              aria-hidden
              key="scan"
              className="pointer-events-none absolute inset-x-4 bottom-0 h-0.5 overflow-hidden rounded-full"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }}
            >
              <span
                className={cn(
                  "block h-full w-1/3 bg-[linear-gradient(90deg,transparent,var(--sheen-accent),transparent)]",
                  !reduced &&
                    "animate-[sheen-indeterminate_var(--sheen-duration-loop-quick)_var(--sheen-ease-in-out)_infinite]",
                )}
              />
            </motion.span>
          )}
        </AnimatePresence>
      </header>

      <p aria-live="polite" className="sr-only">
        {announce}
      </p>
      <p aria-live="polite" className="sr-only">
        {exported ? labels.exported : ""}
      </p>

      <GlassBudgetContext value={glassBudget}>
        <PanelHeadingContext value={Heading === "p" ? "p" : Heading === "h1" ? "h2" : Heading === "h2" ? "h3" : "h4"}>
          {children}
        </PanelHeadingContext>
      </GlassBudgetContext>
    </section>
  );
}

/*
 * The header's controls are memoised pieces, each with its own optimistic state: a click answers
 * at once (only that control re-renders), while the dashboard re-renders in a transition that
 * React renders in slices, so a click never blocks the next frame.
 */

const RangeControl = memo(function RangeControl({
  range,
  ranges,
  onRangeChange,
  labels,
}: {
  range: AnalyticsRange;
  ranges: readonly AnalyticsRange[];
  onRangeChange: (range: AnalyticsRange) => void;
  labels: AnalyticsLabels;
}) {
  const [shown, setShown] = useOptimistic(range);
  // The accessible name starts with the visible text ("7d, Last 7 days"; WCAG 2.5.3 Label in Name), so
  // "click 7d" works for voice control. A long name that already contains the visible text is used as is.
  const items = useMemo(
    () =>
      ranges.map((r) => {
        const text = labels.ranges[r];
        const name = labels.rangeNames[r];
        return {
          value: r,
          label: text,
          "aria-label": name.toLocaleLowerCase().includes(text.toLocaleLowerCase()) ? name : `${text}, ${name}`,
        };
      }),
    [ranges, labels],
  );
  return (
    <SegmentedControl
      aria-label={labels.range}
      size="sm"
      value={shown}
      onValueChange={(v) =>
        startTransition(() => {
          setShown(v as AnalyticsRange);
          onRangeChange(v as AnalyticsRange);
        })
      }
      items={items}
      className={cn(noBlur, "max-w-full")}
    />
  );
});

const FilterChips = memo(function FilterChips({
  filters,
  active,
  onChange,
  label,
}: {
  filters: readonly AnalyticsFilter[];
  active: readonly string[];
  onChange: (filters: string[]) => void;
  label: string;
}) {
  const [shown, setShown] = useOptimistic(active);
  const toggle = (value: string) => {
    const next = shown.includes(value) ? shown.filter((f) => f !== value) : [...shown, value];
    startTransition(() => {
      setShown(next);
      onChange(next);
    });
  };
  return (
    <div role="group" aria-label={label} className="flex min-w-0 flex-wrap items-center gap-1.5">
      {filters.map((f) => (
        <PillToggle
          key={f.value}
          size="sm"
          pressed={shown.includes(f.value)}
          onPressedChange={() => toggle(f.value)}
          check
        >
          {f.label}
        </PillToggle>
      ))}
    </div>
  );
});

const HeaderToggles = memo(function HeaderToggles({
  live,
  compare,
  onLiveChange,
  onCompareChange,
  labels,
}: {
  live: boolean;
  compare: boolean;
  onLiveChange: (live: boolean) => void;
  onCompareChange: (compare: boolean) => void;
  labels: AnalyticsLabels;
}) {
  const [shownLive, setShownLive] = useOptimistic(live);
  const [shownCompare, setShownCompare] = useOptimistic(compare);
  const liveDescId = useId();
  const compareDescId = useId();
  return (
    <>
      <PillToggle
        pressed={shownLive}
        onPressedChange={(next) =>
          startTransition(() => {
            setShownLive(next);
            onLiveChange(next);
          })
        }
        describedBy={liveDescId}
        icon={<LiveDot on={shownLive} />}
      >
        {labels.live}
      </PillToggle>
      <span id={liveDescId} hidden>
        {labels.liveDescription}
      </span>
      <PillToggle
        pressed={shownCompare}
        onPressedChange={(next) =>
          startTransition(() => {
            setShownCompare(next);
            onCompareChange(next);
          })
        }
        describedBy={compareDescId}
        icon={<CompareIcon />}
      >
        {labels.compare}
      </PillToggle>
      <span id={compareDescId} hidden>
        {labels.compareDescription}
      </span>
    </>
  );
});

/** A pill toggle button (aria-pressed). Pressed: accent tint + a shape cue (✓ or a filled dot). */
function PillToggle({
  pressed,
  onPressedChange,
  icon,
  check = false,
  size = "md",
  describedBy,
  children,
}: {
  pressed: boolean;
  onPressedChange: (pressed: boolean) => void;
  icon?: ReactNode;
  check?: boolean;
  size?: "sm" | "md";
  describedBy?: string;
  children: ReactNode;
}) {
  return (
    <button
      type="button"
      aria-pressed={pressed}
      aria-describedby={describedBy}
      onClick={() => onPressedChange(!pressed)}
      className={cn(
        "inline-flex shrink-0 cursor-pointer items-center gap-1.5 rounded-sheen-full border font-medium whitespace-nowrap select-none",
        "touch-manipulation [-webkit-tap-highlight-color:transparent]",
        "transition-[color,background-color,border-color,scale] duration-(--sheen-duration-fast) ease-sheen-out motion-ok:active:scale-[0.97]",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
        size === "sm" ? "h-8 px-3 text-xs any-pointer-coarse:h-11" : "h-9 px-3.5 text-sm any-pointer-coarse:h-11",
        pressed
          ? "border-sheen-accent-border bg-sheen-accent-soft text-sheen-accent"
          : "border-sheen-border text-sheen-fg-muted hover:bg-sheen-hover hover:text-sheen-fg",
        "forced-colors:aria-pressed:border-[Highlight] forced-colors:aria-pressed:underline forced-colors:aria-pressed:decoration-2 forced-colors:aria-pressed:underline-offset-4",
      )}
    >
      {check ? (
        <span
          aria-hidden
          className={cn(
            "grid size-3.5 place-items-center transition-opacity duration-(--sheen-duration-fast)",
            pressed ? "opacity-100" : "-ms-1 w-0 opacity-0",
          )}
        >
          {pressed && <CheckIcon className="size-3.5" />}
        </span>
      ) : (
        icon
      )}
      {children}
    </button>
  );
}

/**
 * The live indicator: a ring that pings while live (paused off-screen and in hidden tabs).
 *
 * Props: `on` (`boolean`, required: pinging ring and filled dot when true, a hollow dot when false) and
 * `className` (`string`). Accessibility: `aria-hidden`; the state is also a shape (filled or hollow) and
 * forced colours use `CanvasText`, so say "Live" in text beside it. Keyboard: none.
 * Motion: the ping runs only while the dot is on screen and the tab is visible, and not at all under
 * reduced motion.
 *
 * @example
 * ```tsx
 * import { LiveDot } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <span className="inline-flex items-center gap-2"><LiveDot on /> Live</span>
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function LiveDot({
  on,
  className,
}: {
  /** Whether the dot pulses: true while live updates are running. */
  on: boolean;
  className?: string;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const visible = useLoopPlayback(ref, { respectReducedMotion: false });
  return (
    <span
      ref={ref}
      aria-hidden
      data-slot="live-dot"
      className={cn("relative inline-flex size-2.5 shrink-0", className)}
    >
      {on && (
        <span
          className="absolute inset-0 rounded-full bg-sheen-success motion-ok:animate-ping"
          style={{ animationPlayState: visible ? "running" : "paused" }}
        />
      )}
      <span
        className={cn(
          "relative size-2.5 rounded-full border-2",
          on ? "border-sheen-success bg-sheen-success" : "border-sheen-fg-subtle bg-transparent",
          "forced-colors:border-[CanvasText]",
          on && "forced-colors:bg-[CanvasText]",
        )}
      />
    </span>
  );
}

/* ====================================================================================
 * Icons (decorative, currentColor)
 * ==================================================================================== */

function DownloadIcon() {
  return (
    <svg
      aria-hidden
      viewBox="0 0 24 24"
      className="size-4"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      <path d="M12 4v11m0 0-4.5-4.5M12 15l4.5-4.5M5 19.5h14" />
    </svg>
  );
}

function CompareIcon() {
  return (
    <svg
      aria-hidden
      viewBox="0 0 24 24"
      className="size-4"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.8}
      strokeLinecap="round"
    >
      <path d="M3 16c3-5 6-7 9-5s6 0 9-5" />
      <path d="M3 20c3-3 6-4 9-3s6-1 9-4" strokeDasharray="2.5 3" />
    </svg>
  );
}

/** Props of {@link LiveDot}. The live indicator: a ring that pings while live (paused off-screen and in hidden tabs). */
export type LiveDotProps = ComponentProps<typeof LiveDot>;

"use client";

import { memo, useId, useMemo } from "react";

import { motion } from "motion/react";
import { cn } from "../../lib/cn";

import { ChartEmpty, type TooltipRow } from "../../charts/chart-parts";
import {
  axisFormat,
  formatCompact,
  linePath,
  slotColor,
  useDataChanged,
  type ChartColor,
} from "../../charts/chart-utils";

import { type AnalyticsLabels, defaultAnalyticsLabels } from "./labels";
import {
  ChartReader,
  FrameAxes,
  type FrameGeometry,
  WipeClip,
  frameGeometry,
  trendSpring,
  useDashChart,
} from "./trend-frame";

/* ---------- StackedTrendChart ---------- */

/** One band of a `StackedTrendChart`: `key` indexes each datum's `values`, `color` is a palette slot. */
export type StackedTrendSeries = { key: string; label: string; color: ChartColor };

/** One x position of a `StackedTrendChart`: a `label`, an optional `long` form for tooltips, and a value per series `key`. */
export type StackedTrendDatum = { label: string; long?: string; values: Record<string, number> };

/** Strings of `StackedTrendChart`: the shared analytics chart strings plus `total`, the tooltip row of the stack total. */
export type StackedTrendChartLabels = Pick<AnalyticsLabels, "chartInstructions" | "touchHint" | "noData"> & {
  /** Tooltip row of the stack total. */
  total: string;
};

/** The English strings of `StackedTrendChart`; spread it into your own `labels` and change what you need. */
export const defaultStackedTrendChartLabels: StackedTrendChartLabels = {
  chartInstructions: defaultAnalyticsLabels.chartInstructions,
  touchHint: defaultAnalyticsLabels.touchHint,
  noData: defaultAnalyticsLabels.noData,
  total: "Total",
};

/** Props of `StackedTrendChart`. */
export type StackedTrendChartProps = {
  /** The x positions, oldest first (`StackedTrendDatum[]`, required). */
  data: StackedTrendDatum[];
  /** Bands from the bottom of the stack up, each with a fixed colour slot. */
  series: StackedTrendSeries[];
  /** Sets the plot height in pixels (`number`, default 280). */
  height?: number;
  /** Formats values in the axis and tooltip (`(n: number) => string`, default compact). */
  format?: (n: number) => string;
  /** Overrides for the chart's strings, including `total` (the tooltip row of the stack total, default "Total"). */
  labels?: Partial<StackedTrendChartLabels>;
  /** Names the chart for assistive tech (`string`, required). */
  "aria-label": string;
  /** Adds extra classes to the chart's wrapper (`string`). */
  className?: string;
};

/**
 * Stacked areas (e.g. MRR by plan): bands separated by a 2px surface line, a crisp top edge,
 * wiped in on first view, morphing on new values. Reading a point shows every band and the total.
 *
 * Props (see `StackedTrendChartProps`): `data`, `series` and `aria-label` are required; `height`
 * (`280`), `format`, `labels` (`labels.total` is the stack-total row, `"Total"`), `className`.
 * Keyboard: Tab focuses the chart; the arrow keys move between x positions, Home and End jump to the
 * ends, Escape clears; each move announces every band and the total.
 * Accessibility: `role="figure"` named by `aria-label`; the bands are told apart by order and the
 * tooltip lists them by name, not by colour alone.
 * Glass and motion: no backdrop blur on the plot; the tooltip is the shared glass surface. Bands draw
 * in once; reduced motion draws them in place.
 *
 * @example
 * ```tsx
 * import { StackedTrendChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <StackedTrendChart
 *       aria-label="Traffic by channel"
 *       series={[{ key: "search", label: "Search", color: 1 }, { key: "social", label: "Social", color: 2 }]}
 *       data={[{ label: "Mon", values: { search: 120, social: 40 } }, { label: "Tue", values: { search: 150, social: 55 } }]}
 *     />
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function StackedTrendChart({
  data,
  series,
  height = 280,
  format = formatCompact,
  labels: labelsProp,
  "aria-label": ariaLabel,
  className,
}: StackedTrendChartProps) {
  const t = { ...defaultStackedTrendChartLabels, ...labelsProp };
  const id = useId().replace(/:/g, "");
  const { ref: chartRef, svgRef, ...c } = useDashChart(height);
  const tickFormat = axisFormat(format === formatCompact ? undefined : format);
  const signature = data.map((d) => series.map((s) => d.values[s.key] ?? 0).join("|")).join(",");

  const geo = useMemo(() => {
    const totals = data.map((d) => series.reduce((sum, s) => sum + Math.max(0, d.values[s.key] ?? 0), 0));
    const g = frameGeometry(
      data.map((d) => d.label),
      Math.max(0, ...totals),
      c.width,
      height,
      c.docked,
      tickFormat,
    );
    // Each band sits on top of the one before it: its `lower` edge is the previous band's `upper`.
    const bands: {
      s: (typeof series)[number];
      color: string;
      edge: string;
      area: string;
      tops: (readonly [number, number])[];
    }[] = [];
    let lower = data.map(() => 0);
    for (const s of series) {
      const upper = data.map((d, i) => (lower[i] ?? 0) + Math.max(0, d.values[s.key] ?? 0));
      const top = upper.map((v, i) => [g.xs[i] ?? 0, g.y(v)] as const);
      const bottom = lower.map((v, i) => [g.xs[i] ?? 0, g.y(v)] as const).reverse();
      const edge = linePath(top, "monotone");
      const back = linePath(bottom, "monotone").replace(/^M/, "L");
      lower = upper;
      bands.push({ s, color: slotColor(s.color), edge, area: `${edge} ${back} Z`, tops: top });
    }
    return { g, bands };
  }, [data, series, c.width, height, c.docked, tickFormat]);

  const layers = useMemo(
    () => (
      <StackedLayers
        geo={geo}
        labels={data}
        id={id}
        shown={c.shown}
        reduced={c.reduced}
        signature={signature}
        tickFormat={tickFormat}
      />
    ),
    [geo, data, id, signature, c.shown, c.reduced, tickFormat],
  );

  if (data.length === 0 || series.length === 0) {
    return (
      <div className={className}>
        <ChartEmpty height={height} aria-label={ariaLabel}>
          {t.noData}
        </ChartEmpty>
      </div>
    );
  }

  const rows = (i: number): TooltipRow[] => {
    const d = data[i];
    if (!d) return [];
    const out = [...series].reverse().map((s) => ({
      label: s.label,
      value: format(d.values[s.key] ?? 0),
      color: slotColor(s.color),
      kind: "rect" as const,
    }));
    out.push({
      label: t.total,
      value: format(series.reduce((sum, s) => sum + Math.max(0, d.values[s.key] ?? 0), 0)),
      color: "transparent",
      kind: "rect",
    });
    return out;
  };
  const marks = (i: number) => (
    <>
      {geo.bands.map((b) => (
        <circle
          key={b.s.key}
          cy={b.tops[i]?.[1] ?? 0}
          r={4}
          fill={b.color}
          stroke="var(--sheen-chart-surface)"
          strokeWidth={2}
        />
      ))}
    </>
  );

  return (
    <div ref={chartRef} className={cn("relative w-full", className)} style={{ height }}>
      {c.width > 0 && (
        <ChartReader
          width={c.width}
          height={height}
          geo={geo.g}
          docked={c.docked}
          items={data}
          layers={layers}
          marks={marks}
          rows={rows}
          reduced={c.reduced}
          svgRef={svgRef}
          ariaLabel={ariaLabel}
          instructions={t.chartInstructions}
          touchHint={t.touchHint}
        />
      )}
    </div>
  );
}

const StackedLayers = memo(function StackedLayers({
  geo,
  labels,
  id,
  shown,
  reduced,
  signature,
  tickFormat,
}: {
  geo: { g: FrameGeometry; bands: { s: StackedTrendSeries; color: string; edge: string; area: string }[] };
  labels: StackedTrendDatum[];
  id: string;
  shown: boolean;
  reduced: boolean;
  /** What the data looks like; compared with the last commit to tell new data (morph) from a resize (no morph). */
  signature: string;
  tickFormat: (n: number) => string;
}) {
  const changed = useDataChanged(signature);
  const { g, bands } = geo;
  const structure = `${labels.length}-${bands.length}`;
  const morph = reduced || !changed ? { duration: 0 } : trendSpring;
  return (
    <>
      <defs>
        {bands.map((b, i) => (
          <linearGradient key={b.s.key} id={`${id}-band-${i}`} x1="0" x2="0" y1="0" y2="1">
            <stop offset="0%" stopColor={b.color} stopOpacity={0.95} />
            <stop offset="100%" stopColor={b.color} stopOpacity={0.62} />
          </linearGradient>
        ))}
        <WipeClip
          id={`${id}-wipe`}
          structure={structure}
          innerW={g.innerW}
          innerH={g.innerH}
          shown={shown}
          reduced={reduced}
        />
      </defs>
      <g aria-hidden transform={`translate(${g.left},${g.top})`}>
        <FrameAxes
          geo={g}
          labels={labels.map((d) => d.label)}
          structure={structure}
          morph={morph}
          tickFormat={tickFormat}
        />
        <g clipPath={`url(#${id}-wipe)`}>
          {bands.map((b, i) => (
            <motion.path
              key={`${b.s.key}-${structure}`}
              fill={`url(#${id}-band-${i})`}
              initial={{ d: b.area }}
              animate={{ d: b.area }}
              transition={{ d: morph }}
            />
          ))}
          {/* 2px surface gap on each band's top edge; the top of the stack gets a crisp line in its colour. */}
          {bands.map((b, i) => (
            <motion.path
              key={`e-${b.s.key}-${structure}`}
              fill="none"
              stroke={i === bands.length - 1 ? b.color : "var(--sheen-chart-surface)"}
              strokeWidth={2}
              strokeLinejoin="round"
              initial={{ d: b.edge }}
              animate={{ d: b.edge }}
              transition={{ d: morph }}
            />
          ))}
        </g>
      </g>
    </>
  );
});

"use client";

import type { ComponentProps } from "react";
import { memo, useId, useMemo } from "react";

import { AnimatePresence, motion } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, ease } from "../../motion/tokens";

import { ChartEmpty, type TooltipRow } from "../../charts/chart-parts";
import {
  areaPath,
  axisFormat,
  chartGlow,
  formatCompact,
  linePath,
  slotColor,
  useDataChanged,
  type ChartColor,
} from "../../charts/chart-utils";

import { changeRatio, formatChange } from "./data";
import { type AnalyticsLabels, defaultAnalyticsLabels } from "./labels";
import { type PanelLegendItem } from "./panel";
import {
  ChartReader,
  FrameAxes,
  type FrameGeometry,
  type Pt,
  WipeClip,
  frameGeometry,
  trendSpring,
  useDashChart,
} from "./trend-frame";

/* ====================================================================================
 * Trend chart: area + dashed previous period
 * ==================================================================================== */

/** One point of a `TrendChart` or `TrendTable`. */
export type TrendDatum = {
  /** Short axis label ("Mon", "14:00"). */
  label: string;
  /** Tooltip / announcement label (defaults to `label`). */
  long?: string;
  /** The measured value (`number`). */
  value: number;
  /** Same point of the previous period. */
  previous?: number | null;
};

/** Props of `TrendChart`. */
export type TrendChartProps = {
  /** The points, oldest first (`TrendDatum[]`, required). */
  data: TrendDatum[];
  /** Sets the name of the series (tooltip, table). */
  seriesLabel: string;
  /** Palette slot (1–8) of the series line and its area. Default 1. */
  color?: ChartColor;
  /** Draw the previous period as a dashed, muted line. */
  compare?: boolean;
  /** Pulse the latest point (live data). */
  live?: boolean;
  /** Sets the plot height in pixels (`number`, default 280). */
  height?: number;
  /** Formats values in the axis and tooltip (`(n: number) => string`, default compact: 12.8K). */
  format?: (n: number) => string;
  /** BCP 47 locale for dates and numbers in announcements (`string`, default the runtime's). */
  locale?: string;
  /** Overrides for the chart's strings (`Partial<Pick<AnalyticsLabels, …>>`). */
  labels?: Partial<
    Pick<AnalyticsLabels, "previousPeriod" | "changeLabel" | "chartInstructions" | "touchHint" | "noData">
  >;
  /** Names the chart for assistive tech (`string`, required). */
  "aria-label": string;
  /** Adds extra classes to the chart's wrapper (`string`). */
  className?: string;
};

/* ---------- TrendChart ---------- */

/**
 * The hero chart of a dashboard: gradient area, 2px line, dashed previous period. It draws in
 * on first view; a new range (another number of points) re-draws; new values on the same points
 * (live ticks, filters, Compare) morph on a spring. Pointer and keyboard read any point.
 *
 * Props (see `TrendChartProps`): `data`, `seriesLabel` and `aria-label` are required; `color` (slot
 * `1`), `compare` (`false`), `live` (`false`), `height` (`280`), `format`, `locale`, `labels`,
 * `className`. Pair it with `TrendTable` for the data table.
 * Keyboard: Tab focuses the chart; Left and Right (or Up and Down) move the crosshair between points,
 * Home and End jump to the first and last, Escape clears. Each move is announced as value, date and
 * change. Touch: press and drag; a hint explains it once.
 * Accessibility: `role="figure"` named by `aria-label`; the instructions are its description; the
 * previous period is a dashed line (a shape cue), not only a lighter colour.
 * Glass and motion: the plot has no backdrop blur; the tooltip is the shared glass surface. The line
 * draws in once; the latest point pulses only while `live` is true and on screen. Reduced motion draws
 * it in place.
 *
 * @example
 * ```tsx
 * import { TrendChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <TrendChart
 *       seriesLabel="Visitors"
 *       aria-label="Visitors per day"
 *       data={[{ label: "Mon", value: 120 }, { label: "Tue", value: 180, previous: 150 }, { label: "Wed", value: 160 }]}
 *       compare
 *     />
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function TrendChart({
  data,
  seriesLabel,
  color = 1,
  compare = false,
  live = false,
  height = 280,
  format = formatCompact,
  locale,
  labels: labelsProp,
  "aria-label": ariaLabel,
  className,
}: TrendChartProps) {
  const t = { ...defaultAnalyticsLabels, ...labelsProp };
  const id = useId().replace(/:/g, "");
  const { ref: chartRef, svgRef, ...c } = useDashChart(height);
  const n = data.length;
  const stroke = slotColor(color);
  const hasPrev = compare && data.some((d) => d.previous !== null && d.previous !== undefined);
  const tickFormat = axisFormat(format === formatCompact ? undefined : format);
  const signature = data.map((d) => `${d.value}|${d.previous ?? ""}`).join(",") + (hasPrev ? "c" : "");

  const geo = useMemo(() => {
    let max = 0;
    for (const d of data) {
      max = Math.max(max, d.value);
      if (hasPrev && d.previous != null) max = Math.max(max, d.previous);
    }
    const g = frameGeometry(
      data.map((d) => d.label),
      max,
      c.width,
      height,
      c.docked,
      tickFormat,
    );
    const points = data.map((d, i) => [g.xs[i] ?? 0, g.y(d.value)] as const);
    const prevPoints = data.map((d, i) => [g.xs[i] ?? 0, g.y(d.previous ?? 0)] as const);
    return {
      g,
      points,
      prevPoints,
      line: linePath(points, "monotone"),
      area: areaPath(points, g.innerH, "monotone"),
      prevLine: linePath(prevPoints, "monotone"),
    };
  }, [data, hasPrev, c.width, height, c.docked, tickFormat]);

  // The layers compare the data signature with the last commit themselves; a later render
  // (reading a point) keeps the same element, so React skips the layers entirely.
  const layers = useMemo(
    () => (
      <TrendLayers
        geo={geo}
        labels={data}
        id={id}
        stroke={stroke}
        hasPrev={hasPrev}
        live={live}
        pulse={c.pulse}
        shown={c.shown}
        reduced={c.reduced}
        signature={signature}
        tickFormat={tickFormat}
      />
    ),
    [geo, data, id, signature, stroke, hasPrev, live, c.pulse, c.shown, c.reduced, tickFormat],
  );

  if (n === 0) {
    return (
      <div className={className}>
        <ChartEmpty height={height} aria-label={ariaLabel}>
          {t.noData}
        </ChartEmpty>
      </div>
    );
  }

  const rows = (i: number): TooltipRow[] => {
    const d = data[i];
    if (!d) return [];
    const out: TooltipRow[] = [{ label: seriesLabel, value: format(d.value), color: stroke }];
    if (hasPrev && d.previous != null) {
      out.push({ label: t.previousPeriod, value: format(d.previous), color: "var(--sheen-fg-subtle)" });
      const r = changeRatio(d.value, d.previous);
      if (r !== null) out.push({ label: t.changeLabel, value: formatChange(r, locale), color: "transparent" });
    }
    return out;
  };
  const marks = (i: number) => (
    <>
      {hasPrev && data[i]?.previous != null && (
        <circle
          cy={geo.prevPoints[i]?.[1]}
          r={3.5}
          fill="var(--sheen-chart-surface)"
          stroke="var(--sheen-fg-subtle)"
          strokeWidth={1.5}
        />
      )}
      <circle
        cy={geo.points[i]?.[1]}
        r={5}
        fill={stroke}
        stroke="var(--sheen-chart-surface)"
        strokeWidth={2}
        style={{ filter: chartGlow(stroke, 8) }}
      />
    </>
  );

  return (
    <div ref={chartRef} className={cn("relative w-full", className)} style={{ height }}>
      {c.width > 0 && (
        <ChartReader
          width={c.width}
          height={height}
          geo={geo.g}
          docked={c.docked}
          items={data}
          layers={layers}
          marks={marks}
          rows={rows}
          reduced={c.reduced}
          svgRef={svgRef}
          ariaLabel={ariaLabel}
          instructions={t.chartInstructions}
          touchHint={t.touchHint}
        />
      )}
    </div>
  );
}

const TrendLayers = memo(function TrendLayers({
  geo,
  labels,
  id,
  stroke,
  hasPrev,
  live,
  pulse,
  shown,
  reduced,
  signature,
  tickFormat,
}: {
  geo: { g: FrameGeometry; points: Pt[]; line: string; area: string; prevLine: string };
  labels: TrendDatum[];
  id: string;
  stroke: string;
  hasPrev: boolean;
  live: boolean;
  pulse: boolean;
  shown: boolean;
  reduced: boolean;
  /** What the data looks like; compared with the last commit to tell new data (morph) from a resize (no morph). */
  signature: string;
  tickFormat: (n: number) => string;
}) {
  const changed = useDataChanged(signature);
  const { g, points, line, area, prevLine } = geo;
  const n = points.length;
  // Same number of points → morph; a new count (another range) → re-draw.
  const structure = String(n);
  const morph = reduced || !changed ? { duration: 0 } : trendSpring;
  const last = points[n - 1] ?? ([0, 0] as const);
  return (
    <>
      <defs>
        <linearGradient id={`${id}-fill`} x1="0" x2="0" y1="0" y2="1">
          <stop offset="0%" stopColor={stroke} stopOpacity={0.3} />
          <stop offset="55%" stopColor={stroke} stopOpacity={0.09} />
          <stop offset="100%" stopColor={stroke} stopOpacity={0} />
        </linearGradient>
        <WipeClip
          id={`${id}-wipe`}
          structure={structure}
          innerW={g.innerW}
          innerH={g.innerH}
          shown={shown}
          reduced={reduced}
        />
      </defs>

      <g aria-hidden transform={`translate(${g.left},${g.top})`}>
        <FrameAxes
          geo={g}
          labels={labels.map((d) => d.label)}
          structure={structure}
          morph={morph}
          tickFormat={tickFormat}
        />

        <g clipPath={`url(#${id}-wipe)`}>
          <motion.path
            key={`a-${structure}`}
            fill={`url(#${id}-fill)`}
            initial={{ d: area }}
            animate={{ d: area }}
            transition={{ d: morph }}
          />
          <AnimatePresence>
            {hasPrev && (
              <motion.path
                key={`p-${structure}`}
                fill="none"
                stroke="var(--sheen-fg-subtle)"
                strokeWidth={1.5}
                strokeDasharray="4 5"
                strokeLinecap="round"
                initial={{ opacity: 0, d: prevLine }}
                animate={{ opacity: 1, d: prevLine }}
                exit={{ opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }}
                transition={{ d: morph, opacity: { duration: duration.slow } }}
              />
            )}
          </AnimatePresence>
        </g>

        <motion.path
          key={`l-${structure}`}
          fill="none"
          stroke={stroke}
          strokeWidth={2}
          strokeLinecap="round"
          strokeLinejoin="round"
          initial={{ pathLength: reduced ? 1 : 0, d: line }}
          animate={{ pathLength: shown ? 1 : 0, d: line }}
          transition={{ pathLength: { duration: reduced ? 0 : duration.slower, ease: ease.out }, d: morph }}
        />

        {/* Latest point: a dot with a surface ring, pinging while live (paused off-screen). */}
        {live && (
          <motion.circle
            r={4}
            fill={stroke}
            className="[transform-box:fill-box] [transform-origin:center] motion-ok:animate-ping"
            style={{ animationPlayState: pulse ? "running" : "paused" }}
            initial={false}
            animate={{ cx: last[0], cy: last[1] }}
            transition={morph}
          />
        )}
        <motion.circle
          r={4}
          fill={stroke}
          stroke="var(--sheen-chart-surface)"
          strokeWidth={2}
          initial={{ opacity: 0, cx: last[0], cy: last[1] }}
          animate={{ opacity: shown ? 1 : 0, cx: last[0], cy: last[1] }}
          transition={{ cx: morph, cy: morph, opacity: { duration: duration.base, delay: reduced ? 0 : 0.8 } }}
        />
      </g>
    </>
  );
});

/**
 * Table view of a TrendChart.
 *
 * Props: `data` (`TrendDatum[]`), `seriesLabel` (`string`) and `indexLabel` (`string`, the first
 * column's heading) are required; `compare` (`boolean`, adds previous-period and change columns),
 * `format` (default compact), `locale`, `labels` (`Partial<Pick<AnalyticsLabels, "previousPeriod" |
 * "changeLabel" | "noData">>`) and `caption` (`string`, hidden caption that also names the region).
 * Pass it to `AnalyticsPanel`'s `table` prop.
 * Keyboard: the table sits in a scrollable region that is itself a tab stop, so keyboard users can
 * scroll it with the arrow keys; the header row stays pinned.
 * Accessibility: a real `<table>` with column headers; the region is labelled by `caption`.
 * Glass and motion: a solid header over the panel's glass; static (no motion).
 *
 * @example
 * ```tsx
 * import { TrendTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <TrendTable
 *       indexLabel="Day"
 *       seriesLabel="Visitors"
 *       caption="Visitors per day"
 *       data={[{ label: "Mon", value: 120 }, { label: "Tue", value: 180 }]}
 *     />
 *   );
 * }
 * ```
 *
 * @see /dashboards/web-analytics
 */
export function TrendTable({
  data,
  seriesLabel,
  compare,
  format = formatCompact,
  indexLabel,
  locale,
  labels: labelsProp,
  caption,
}: {
  /** The time series to list: one object per point, with the current and optional previous value of each series. */
  data: TrendDatum[];
  /** Header of the value column, for example "Visitors". */
  seriesLabel: string;
  /** Add a previous-period column and a change column. */
  compare?: boolean;
  /** Formats each number in the table. */
  format?: (n: number) => string;
  /** Header of the first column, for example "Day". */
  indexLabel: string;
  /** BCP 47 locale for dates and numbers; defaults to the runtime's locale. */
  locale?: string;
  /** Overrides for the table's built-in English strings. */
  labels?: Partial<Pick<AnalyticsLabels, "previousPeriod" | "changeLabel" | "noData">>;
  /** Visually hidden caption that names the table and its scroll region. */
  caption?: string;
}) {
  const t = { ...defaultAnalyticsLabels, ...labelsProp };
  return (
    <div
      role="group"
      aria-label={caption ?? seriesLabel}
      // eslint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- a scrollable region must be keyboard-focusable so the table can be scrolled without a mouse (WCAG 2.1.1, axe scrollable-region-focusable)
      tabIndex={0}
      className="relative max-h-80 overflow-auto overscroll-contain rounded-sheen-sm [scrollbar-width:thin]"
    >
      <table className="w-full text-start [:where(&)_th]:text-start text-sm">
        {caption && <caption className="sr-only">{caption}</caption>}
        <thead className="sticky top-0 text-xs text-sheen-fg-muted [background:var(--sheen-surface-solid)]">
          <tr className="border-b border-sheen-border">
            <th scope="col" className="py-2 pe-4 font-medium">
              {indexLabel}
            </th>
            <th scope="col" className="py-2 pe-4 text-end font-medium">
              {seriesLabel}
            </th>
            {compare && (
              <>
                <th scope="col" className="py-2 pe-4 text-end font-medium">
                  {t.previousPeriod}
                </th>
                <th scope="col" className="py-2 pe-4 text-end font-medium">
                  {t.changeLabel}
                </th>
              </>
            )}
          </tr>
        </thead>
        <tbody>
          {data.length === 0 ? (
            <tr>
              <td colSpan={compare ? 4 : 2} className="py-6 text-center text-sheen-fg-muted">
                {t.noData}
              </td>
            </tr>
          ) : (
            data.map((d, i) => {
              const r = changeRatio(d.value, d.previous);
              return (
                <tr key={i} className="border-b border-sheen-border last:border-0">
                  <th scope="row" className="py-2 pe-4 font-normal whitespace-nowrap text-sheen-fg-muted">
                    {d.long ?? d.label}
                  </th>
                  <td className="py-2 pe-4 text-end tabular-nums">{format(d.value)}</td>
                  {compare && (
                    <>
                      <td className="py-2 pe-4 text-end text-sheen-fg-muted tabular-nums">
                        {d.previous != null ? format(d.previous) : "–"}
                      </td>
                      <td className="py-2 pe-4 text-end tabular-nums">{r !== null ? formatChange(r, locale) : "–"}</td>
                    </>
                  )}
                </tr>
              );
            })
          )}
        </tbody>
      </table>
    </div>
  );
}

/** Legend items for a trend chart (series + dashed previous period when comparing). */
export function trendLegend(
  seriesLabel: string,
  color: ChartColor,
  compare: boolean,
  previousLabel: string,
): PanelLegendItem[] {
  return compare
    ? [
        { label: seriesLabel, color: slotColor(color), kind: "line" },
        { label: previousLabel, color: "var(--sheen-fg-subtle)", kind: "dashed" },
      ]
    : [];
}

/** Props of {@link TrendTable}. Table view of a TrendChart. */
export type TrendTableProps = ComponentProps<typeof TrendTable>;

"use client";

import { useRef, useState, type ReactNode, type RefObject } from "react";

import { AnimatePresence, motion } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, ease, follow } from "../../motion/tokens";
import { useSheenReducedMotion } from "../../hooks/use-preferences";

import { ChartAnnouncer, ChartTooltip, type TooltipRow } from "../../charts/chart-parts";
import {
  chartFocusClass,
  chartKeyHandler,
  clamp,
  linear,
  niceTicks,
  thinLabels,
  useElementWidth,
  TOOLTIP_DOCK_BELOW,
  useInViewSettled,
} from "../../charts/chart-utils";

import { useLoopPlayback } from "../../motion/gate";
import { ChartFigure } from "../../charts/chart-figure";

/** The spring of the trend charts' hover marker and highlight. */
export const trendSpring = { type: "spring" as const, visualDuration: 0.3, bounce: 0 };

const followPointer = { type: "spring" as const, ...follow.pointer };

/** A point as `[x, y]`. */
export type Pt = readonly [number, number];

/* ---------- Shared frame: geometry, axes and a cheap reading overlay ---------- */

/** The geometry of a chart frame: the ticks and their y positions, the plot area, the x of each point and the y scale. */
export type FrameGeometry = {
  ticks: number[];
  tickY: number[];
  left: number;
  top: number;
  innerW: number;
  innerH: number;
  /** x of each point (band mode: the centre of its slot). */
  xs: number[];
  /** Width of one slot (band mode) or the distance between points. */
  step: number;
  y: (v: number) => number;
  shownLabels: Set<number>;
  band: boolean;
};

/** Computes the frame geometry (ticks, margins and scales) from the labels, the largest value and the size (pure). */
export function frameGeometry(
  labels: string[],
  max: number,
  width: number,
  height: number,
  docked: boolean,
  tickFormat: (n: number) => string,
  band = false,
): FrameGeometry {
  const ticks = niceTicks(0, max > 0 ? max : 1, height < 230 ? 3 : 4);
  const hi = ticks[ticks.length - 1] ?? 1;
  const longest = ticks.reduce((m, tk) => Math.max(m, tickFormat(tk).length), 0);
  const left = Math.max(30, Math.round(longest * 6.6 + 14));
  const top = docked ? 46 : 14;
  const innerW = Math.max(0, width - left - 14);
  const innerH = Math.max(0, height - top - 26);
  const n = labels.length;
  const step = band ? innerW / Math.max(1, n) : n > 1 ? innerW / (n - 1) : innerW;
  const xs = labels.map((_, i) => (band ? (i + 0.5) * step : n <= 1 ? innerW / 2 : i * step));
  const yScale = linear(0, hi, innerH, 0);
  const y = (v: number) => clamp(yScale(Math.max(0, v)), 0, innerH);
  return {
    ticks,
    tickY: ticks.map(y),
    left,
    top,
    innerW,
    innerH,
    xs,
    step,
    y,
    shownLabels: thinLabels(labels, step),
    band,
  };
}

/** Grid lines, y ticks (they glide when the scale changes) and thinned x labels. */
export function FrameAxes({
  geo,
  labels,
  structure,
  morph,
  tickFormat,
}: {
  geo: FrameGeometry;
  labels: string[];
  structure: string;
  morph: object;
  tickFormat: (n: number) => string;
}) {
  const { ticks, tickY, innerW, innerH, xs, shownLabels, band } = geo;
  const n = labels.length;
  return (
    <>
      <AnimatePresence initial={false}>
        {ticks.map((tk, i) => (
          <motion.g
            key={tk}
            initial={{ opacity: 0, y: tickY[i] }}
            animate={{ opacity: 1, y: tickY[i] }}
            exit={{ opacity: 0, transition: { duration: duration.exit, ease: ease.exit } }}
            transition={{ y: morph, opacity: { duration: duration.base } }}
          >
            <line x2={innerW} stroke={tk === 0 ? "var(--sheen-border)" : "var(--sheen-chart-grid)"} strokeWidth={1} />
            <text x={-10} dy="0.32em" textAnchor="end" className="fill-sheen-fg-muted text-2xs tabular-nums">
              {tickFormat(tk)}
            </text>
          </motion.g>
        ))}
      </AnimatePresence>
      {labels.map((label, i) =>
        shownLabels.has(i) ? (
          <text
            key={`${structure}-${i}`}
            x={xs[i]}
            y={innerH + 18}
            textAnchor={band || n <= 1 ? "middle" : i === n - 1 ? "end" : i === 0 ? "start" : "middle"}
            className="fill-sheen-fg-muted text-2xs"
          >
            {label}
          </text>
        ) : null,
      )}
    </>
  );
}

type ChartReaderProps = {
  width: number;
  height: number;
  geo: FrameGeometry;
  docked: boolean;
  items: { label: string; long?: string }[];
  /** The plotted layers, memoised by the caller: reading a point never re-renders them. */
  layers: ReactNode;
  /** Marks for the point being read, drawn at x = 0 (the overlay moves to the point). */
  marks: (i: number) => ReactNode;
  rows: (i: number) => TooltipRow[];
  reduced: boolean;
  svgRef: RefObject<SVGSVGElement | null>;
  ariaLabel: string;
  instructions: string;
  touchHint: string;
};

/**
 * The interactive part of a dashboard chart: the focusable SVG, pointer / touch / keyboard
 * reading, the crosshair (gliding on the pointer spring), the glass tooltip (docked on phones)
 * and the announcer. Only this re-renders while a point is read.
 */
export function ChartReader({
  width,
  height,
  geo,
  docked,
  items,
  layers,
  marks,
  rows,
  reduced,
  svgRef,
  ariaLabel,
  instructions,
  touchHint,
}: ChartReaderProps) {
  const [active, setActive] = useState<number | null>(null);
  const n = items.length;
  const act = active !== null && active < n ? active : null;
  const item = act !== null ? items[act] : undefined;
  const tooltipRows = act !== null ? rows(act) : [];
  const { left, top, innerW, innerH, xs, band } = geo;

  function onPointer(event: React.PointerEvent<SVGRectElement>) {
    const rect = event.currentTarget.getBoundingClientRect();
    const t = (event.clientX - rect.left) / Math.max(1, rect.width);
    const i = band ? Math.floor(t * n) : Math.round(t * (n - 1));
    setActive(n <= 1 ? 0 : clamp(i, 0, n - 1));
  }

  return (
    <>
      <ChartFigure
        as="svg"
        ref={svgRef}
        width={width}
        height={height}
        label={ariaLabel}
        description={instructions}
        tabIndex={0}
        onKeyDown={chartKeyHandler(n, act, setActive)}
        onBlur={() => setActive(null)}
        className={cn(
          "block touch-pan-y touch-pinch-zoom overflow-visible rounded-sheen-sm forced-color-adjust-none",
          chartFocusClass,
        )}
      >
        {layers}
        <g aria-hidden transform={`translate(${left},${top})`}>
          {act !== null && (
            <motion.g
              pointerEvents="none"
              initial={false}
              animate={{ x: xs[act] ?? 0 }}
              transition={reduced ? { duration: 0 } : followPointer}
            >
              {!band && <line y2={innerH} stroke="var(--sheen-fg-subtle)" strokeWidth={1} />}
              {marks(act)}
            </motion.g>
          )}
          <rect
            width={innerW}
            height={innerH}
            fill="transparent"
            style={{ touchAction: "pan-y pinch-zoom" }}
            onPointerDown={onPointer}
            onPointerMove={onPointer}
            onPointerLeave={(e) => e.pointerType === "mouse" && setActive(null)}
          />
        </g>
      </ChartFigure>
      {docked && !item && (
        <p
          aria-hidden
          className="pointer-events-none absolute inset-x-0 top-0 flex min-h-7.5 items-center rounded-sheen-md px-3 text-xs text-sheen-fg-muted"
        >
          {touchHint}
        </p>
      )}
      {item && act !== null && (
        <ChartTooltip
          title={item.long ?? item.label}
          rows={tooltipRows}
          x={left + (xs[act] ?? 0)}
          y={top + innerH / 2}
          containerWidth={width}
          docked={docked}
        />
      )}
      <ChartAnnouncer
        text={item ? `${item.long ?? item.label}: ${tooltipRows.map((r) => `${r.label} ${r.value}`).join(", ")}` : ""}
      />
    </>
  );
}

/** Shared state of the dashboard charts: width, first view, reduced motion, live pulse visibility. */
export function useDashChart(height: number) {
  const reduced = useSheenReducedMotion();
  const [ref, width] = useElementWidth<HTMLDivElement>();
  const svgRef = useRef<SVGSVGElement>(null);
  // The svg only exists once the width is measured: observe it from then on (an effect that ran before it mounted would never run again).
  const seen = useInViewSettled(svgRef, { amount: 0.3, ready: width > 0 });
  const pulse = useLoopPlayback(svgRef, { respectReducedMotion: false });
  const docked = width > 0 && width < TOOLTIP_DOCK_BELOW;
  return { reduced, ref, width, svgRef, shown: reduced || seen, pulse, docked, height };
}

/** The clip that wipes the plot in from the start on first view and on every new range. */
export function WipeClip({
  id,
  structure,
  innerW,
  innerH,
  shown,
  reduced,
}: {
  id: string;
  structure: string;
  innerW: number;
  innerH: number;
  shown: boolean;
  reduced: boolean;
}) {
  return (
    <clipPath id={id}>
      <motion.rect
        key={structure}
        x={-4}
        y={-12}
        width={innerW + 12}
        height={innerH + 24}
        style={{ originX: 0, transformBox: "fill-box" }}
        initial={{ scaleX: reduced ? 1 : 0 }}
        animate={{ scaleX: shown ? 1 : 0 }}
        transition={{ duration: reduced ? 0 : 0.9, ease: ease.out }}
      />
    </clipPath>
  );
}

/** The cubic ease-out curve: maps 0-1 to 0-1, fast at first. */
export const easeOutCubic = (x: number) => 1 - (1 - x) ** 3;

